{ten: "Bánh óc chó Hodu-gwaja", goc: "호두과자 · Hodu-gwaja", am_thuc: "han", vung: "Cheonan", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh nướng nhỏ hình quả óc chó, nhân đậu đỏ và một mẩu óc chó thật, mua ở trạm dừng xa lộ."},
{ten: "Nước gạo Sikhye", goc: "식혜 · Sikhye", am_thuc: "han", vung: "Seoul", bua: ["trua", "toi"], loai: "douong", mo_ta: "Nước gạo ngọt mát với những hạt cơm nổi lững lờ, uống lạnh sau khi tắm xông hơi là đúng kiểu Hàn."},
{ten: "Trà quế Sujeonggwa", goc: "수정과 · Sujeonggwa", am_thuc: "han", vung: "Seoul", bua: ["trua", "toi"], loai: "douong", mo_ta: "Nước quế gừng nấu với đường, thả hồng khô và hạt thông, uống lạnh cay ấm thơm nồng."},
{ten: "Trà thanh yên Yuja", goc: "유자차 · Yuja-cha", am_thuc: "han", vung: "Seoul", bua: ["sang", "trua", "toi"], loai: "douong", mo_ta: "Mứt thanh yên thái sợi pha nước nóng, chua ngọt thơm như cam, uống những ngày se lạnh."},
{ten: "Cà phê Dalgona", goc: "달고나 커피 · Dalgona keopi", am_thuc: "han", vung: "Seoul", bua: ["trua", "toi"], loai: "douong", mo_ta: "Cà phê hòa tan đánh bông với đường thành lớp kem nâu đặt trên sữa lạnh, khuấy lên rồi uống."},

// Thái Lan
{ten: "Pad Thái", goc: "ผัดไทย · Phat Thai", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi", "khuya"], loai: "kho", mo_ta: "Bánh phở xào me chua ngọt với tôm, đậu hũ, trứng, giá đỗ, rắc đậu phộng và vắt chanh lên trên."},
{ten: "Tom Yum Goong", goc: "ต้มยำกุ้ง · Tom yam kung", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Canh tôm chua cay thơm sả, riềng, lá chanh, nấm rơm, húp một thìa là tỉnh cả người."},
{ten: "Tom Kha Gai", goc: "ต้มข่าไก่ · Tom kha kai", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Canh gà nấu nước cốt dừa với riềng, sả, lá chanh, chua nhẹ béo ngậy, dịu hơn tom yum."},
{ten: "Som Tam", goc: "ส้มตำ", am_thuc: "thai", vung: "Isan", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Đu đủ xanh giã cối với ớt, tỏi, chanh, nước mắm, cà chua và đậu phộng, chua cay giòn mát."},
{ten: "Cà ri xanh Thái", goc: "แกงเขียวหวาน · Kaeng khiao wan", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Cà ri nước cốt dừa xanh lá ớt và húng quế, gà, cà tím tròn, cay ngọt thơm, chan cơm hay bún."},
{ten: "Cà ri đỏ Thái", goc: "แกงเผ็ด · Kaeng phet", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Cà ri đỏ ớt khô và nước cốt dừa với thịt vịt hoặc heo, măng, lá chanh, cay nồng sánh béo."},
{ten: "Cà ri Massaman", goc: "แกงมัสมั่น · Kaeng matsaman", am_thuc: "thai", vung: "Miền Nam Thái Lan", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Cà ri thơm quế, hồi, bạch đậu khấu với thịt bò, khoai tây và đậu phộng, béo ngọt dịu cay."},
{ten: "Cà ri Panang", goc: "พะแนง · Phanaeng", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cà ri sệt đặc nước cốt dừa với thịt bò thái mỏng và lá chanh thái chỉ, mặn ngọt đậm đà."},
{ten: "Canh chua cà ri Gaeng Som", goc: "แกงส้ม · Kaeng som", am_thuc: "thai", vung: "Miền Nam Thái Lan", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Canh cà ri chua me với cá và rau củ, không có nước cốt dừa, chua cay rát lưỡi kiểu miền Nam."},
{ten: "Cà ri Hang Lay", goc: "แกงฮังเล · Kaeng hang le", am_thuc: "thai", vung: "Chiang Mai", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt ba chỉ heo hầm gừng, tỏi, me, không nước cốt dừa, ngọt sâu, mang dấu ấn Myanmar."},
{ten: "Khao Soi", goc: "ข้าวซอย", am_thuc: "thai", vung: "Chiang Mai", bua: ["sang", "trua", "toi"], loai: "nuoc", mo_ta: "Mì trứng trong nước cà ri dừa vàng, phủ mì chiên giòn, ăn kèm cải chua, hành tím và chanh."},
{ten: "Thịt xào húng quế Pad Krapow", goc: "ผัดกะเพรา · Phat kaphrao", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi", "khuya"], loai: "kho", mo_ta: "Thịt băm xào lá húng quế thánh và ớt cay, đặt lên cơm với trứng ốp la giòn viền, món quốc dân."},
{ten: "Pad See Ew", goc: "ผัดซีอิ๊ว · Phat si-io", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh phở bản to xào nước tương ngọt với trứng, cải làn và thịt, hơi cháy cạnh thơm khói chảo."},
{ten: "Hủ tiếu sốt Rad Na", goc: "ราดหน้า · Rat na", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh phở bản to áp chảo rưới sốt sánh với thịt heo và cải làn, thêm giấm ớt cho tròn vị."},
{ten: "Mì xào Pad Kee Mao", goc: "ผัดขี้เมา · Phat khi mao", am_thuc: "thai", vung: "Bangkok", bua: ["toi", "khuya"], loai: "kho", mo_ta: "Bánh phở to xào ớt tươi, tỏi và húng quế thánh, cay rát, tên món có nghĩa là món của người say."},
{ten: "Cơm gà Khao Man Gai", goc: "ข้าวมันไก่ · Khao man kai", am_thuc: "thai", vung: "Bangkok", bua: ["sang", "trua"], loai: "kho", mo_ta: "Gà luộc mềm trên cơm nấu nước gà, chấm sốt tương đậu gừng tỏi ớt, kèm bát canh nhỏ."},
{ten: "Cơm chiên Thái", goc: "ข้าวผัด · Khao phat", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cơm chiên với trứng, hành, cà chua và tôm hoặc cua, vắt chanh, chấm nước mắm ớt."},
{ten: "Cơm xá xíu Khao Moo Daeng", goc: "ข้าวหมูแดง · Khao mu daeng", am_thuc: "thai", vung: "Bangkok", bua: ["trua"], loai: "kho", mo_ta: "Thịt heo nướng đỏ thái lát và heo giòn trên cơm, rưới nước sốt sánh ngọt, kèm trứng luộc."},
{ten: "Cơm chân giò Thái", goc: "ข้าวขาหมู · Khao kha mu", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "kho", mo_ta: "Chân giò kho ngũ vị mềm rục trên cơm, thêm trứng kho, cải chua và ớt ngâm giấm."},
{ten: "Larb", goc: "ลาบ · Lap", am_thuc: "thai", vung: "Isan", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Thịt băm trộn thính gạo rang, bạc hà, hành tím, chanh, ớt và nước mắm, ăn kèm xôi và rau sống."},
{ten: "Gỏi bò nướng Nam Tok", goc: "น้ำตก · Nam tok", am_thuc: "thai", vung: "Isan", bua: ["toi"], loai: "anvat", mo_ta: "Bò nướng tái thái mỏng trộn thính, ớt khô, bạc hà và chanh, chua cay thơm khói than."},
{ten: "Gà nướng Isan", goc: "ไก่ย่าง · Kai yang", am_thuc: "thai", vung: "Isan", bua: ["toi"], loai: "nuong", mo_ta: "Gà ướp tỏi, ngò, tiêu nướng than vàng, chấm sốt jaew ớt khô, ăn với xôi và som tam."},
{ten: "Thịt xiên nướng Moo Ping", goc: "หมูปิ้ง · Mu ping", am_thuc: "thai", vung: "Bangkok", bua: ["sang"], loai: "nuong", mo_ta: "Xiên thịt heo ướp nước cốt dừa nướng than ngọt mềm, ăn với gói xôi nhỏ, bữa sáng vỉa hè."},
{ten: "Mookata", goc: "หมูกระทะ · Mu kratha", am_thuc: "thai", vung: "Bangkok", bua: ["toi", "khuya"], loai: "nuong", mo_ta: "Chảo nướng vòm ở giữa, nồi lẩu bao quanh, thịt nướng chảy mỡ xuống làm ngọt nước lẩu."},
{ten: "Suki Thái", goc: "สุกี้ · Suki", am_thuc: "thai", vung: "Bangkok", bua: ["toi"], loai: "nuong", mo_ta: "Lẩu nhúng thịt, hải sản, rau và miến, chấm sốt suki ớt tỏi chua ngọt đặc trưng kiểu Thái."},
{ten: "Mì thuyền", goc: "ก๋วยเตี๋ยวเรือ · Kuai tiao ruea", am_thuc: "thai", vung: "Ayutthaya", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Bát mì nhỏ nước dùng sẫm đậm vị, thịt bò hoặc heo, ăn liền năm sáu bát mới thấy đủ."},
{ten: "Kuay Jab", goc: "ก๋วยจั๊บ · Kuai chap", am_thuc: "thai", vung: "Bangkok", bua: ["toi", "khuya"], loai: "nuoc", mo_ta: "Bánh cuộn ống trong nước dùng tiêu cay nồng với lòng heo và heo giòn, ăn khuya rất ấm."},
{ten: "Bún hồng Yen Ta Fo", goc: "เย็นตาโฟ · Yen ta fo", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Nước dùng hồng từ chao đỏ chua ngọt, cá viên, mực, rau muống, màu sắc lạ mà ngon."},
{ten: "Bún cà ri cá Khanom Jeen", goc: "ขนมจีนน้ำยา · Khanom chin nam ya", am_thuc: "thai", vung: "Miền Nam Thái Lan", bua: ["sang", "trua"], loai: "nuoc", mo_ta: "Bún gạo lên men chan nước cà ri cá xay béo cay, ăn kèm đĩa rau sống và trứng luộc."},
{ten: "Cháo Jok Thái", goc: "โจ๊ก · Chok", am_thuc: "thai", vung: "Bangkok", bua: ["sang", "khuya"], loai: "nuoc", mo_ta: "Cháo gạo nhuyễn mịn với viên thịt heo, gừng sợi và trứng lòng đào, rắc tiêu, bữa sáng ấm áp."},
{ten: "Cá nướng muối Pla Pao", goc: "ปลาเผา · Pla pao", am_thuc: "thai", vung: "Bangkok", bua: ["toi"], loai: "nuong", mo_ta: "Cá rô phi nhồi sả, bọc muối nướng than, bóc lớp vỏ muối là thịt trắng ngọt, cuốn rau chấm sốt."},
{ten: "Cá chẽm hấp chanh Thái", goc: "ปลากะพงนึ่งมะนาว · Pla kaphong nueng manao", am_thuc: "thai", vung: "Bangkok", bua: ["toi"], loai: "kho", mo_ta: "Cá chẽm hấp trong nước chanh, tỏi, ớt chua cay sôi lăn tăn trên bếp cồn, thịt cá ngọt mềm."},
{ten: "Tôm nướng miến nồi đất", goc: "กุ้งอบวุ้นเส้น · Kung op wun sen", am_thuc: "thai", vung: "Bangkok", bua: ["toi"], loai: "nuong", mo_ta: "Tôm sú nằm trên miến thấm nước tương, gừng, tiêu, nướng trong nồi đất, miến ngon chẳng kém tôm."},
{ten: "Cua xào bột cà ri", goc: "ปูผัดผงกะหรี่ · Pu phat phong kari", am_thuc: "thai", vung: "Bangkok", bua: ["toi"], loai: "kho", mo_ta: "Cua xào bột cà ri với trứng thành sốt vàng sánh béo, chan cơm trắng là không cần gì thêm."},
{ten: "Chả cá Thái Tod Mun", goc: "ทอดมันปลา · Thot man pla", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Chả cá trộn cà ri đỏ, lá chanh và đậu đũa chiên dai, chấm dưa leo ngâm chua ngọt."},
{ten: "Gỏi miến Thái", goc: "ยำวุ้นเส้น · Yam wun sen", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Miến trộn tôm, thịt băm, hành tây, cần tây với nước trộn chua cay mặn ngọt, mát mà cay."},
{ten: "Xúc xích Sai Ua", goc: "ไส้อั่ว · Sai ua", am_thuc: "thai", vung: "Chiang Mai", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Xúc xích heo nhồi sả, riềng, lá chanh và ớt nướng than, thơm thảo mộc đặc trưng miền Bắc Thái."},
{ten: "Xúc xích chua Isan", goc: "ไส้กรอกอีสาน · Sai krok Isan", am_thuc: "thai", vung: "Isan", bua: ["toi", "khuya"], loai: "nuong", mo_ta: "Xúc xích thịt heo và cơm lên men chua nhẹ, nướng vàng, ăn kèm gừng, ớt và bắp cải."},
{ten: "Miang Kham", goc: "เมี่ยงคำ", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Lá lốt Thái gói dừa rang, đậu phộng, gừng, chanh, hành, tôm khô, rưới sốt ngọt, một miếng đủ vị."},
{ten: "Xôi xoài", goc: "ข้าวเหนียวมะม่วง · Khao niao mamuang", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Xôi nếp dẻo thấm nước cốt dừa mặn ngọt, ăn với xoài chín vàng thơm lừng, rắc đậu xanh giòn."},
{ten: "Bánh Khanom Krok", goc: "ขนมครก · Khanom khrok", am_thuc: "thai", vung: "Bangkok", bua: ["sang", "toi"], loai: "anvat", mo_ta: "Bánh dừa đổ khuôn tròn nhỏ, viền giòn, lòng mềm béo như kem, rắc hành lá hoặc bắp ngọt."},
{ten: "Roti chuối", goc: "โรตีกล้วย · Roti kluai", am_thuc: "thai", vung: "Bangkok", bua: ["toi", "khuya"], loai: "anvat", mo_ta: "Bánh bột mỏng chiên giòn bọc chuối và trứng, rưới sữa đặc, món ngọt bán xe đẩy về đêm."},
{ten: "Chè Bua Loy", goc: "บัวลอย · Bua loi", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Viên bột nếp nhiều màu trong nước cốt dừa ấm, ngọt béo, đôi khi thêm trứng ngọt lòng đào."},
{ten: "Bánh Khanom Buang", goc: "ขนมเบื้อง · Khanom bueang", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh tráng giòn mỏng như vỏ ốc quế, phết kem lòng trắng trứng và sợi trứng vàng ngọt."},
{ten: "Trà sữa Thái", goc: "ชาเย็น · Cha yen", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "douong", mo_ta: "Trà đỏ cam pha sữa đặc và sữa tươi, rót trên đá, ngọt béo đậm màu, chất trà Thái chính hiệu."},
{ten: "Cà phê Oliang", goc: "โอเลี้ยง · O-liang", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "douong", mo_ta: "Cà phê đen pha từ hỗn hợp hạt rang, ngọt đường, uống với đá, đậm đà kiểu quán cóc Thái."},
{ten: "Sữa hồng Nom Yen", goc: "นมเย็น · Nom yen", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "douong", mo_ta: "Sữa tươi pha siro sala hồng phấn, ngọt thơm như kẹo, uống lạnh mát, trẻ con người lớn đều mê."},
{ten: "Kem dừa Thái", goc: "ไอศกรีมกะทิ · Ai-sa-khrim kathi", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Kem nước cốt dừa trong gáo dừa với xôi, đậu phộng và cơm dừa non, mát lạnh giữa ngày nắng."},
{ten: "Gà xào hạt điều", goc: "ไก่ผัดเม็ดมะม่วงหิมพานต์ · Kai phat met mamuang", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà chiên xào hạt điều, ớt khô, hành tây với sốt ngọt mặn, giòn bùi, ăn với cơm trắng."},
{ten: "Heo chiên tỏi", goc: "หมูทอดกระเทียม · Mu thot krathiam", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt heo ướp chiên vàng với rất nhiều tỏi phi giòn, mặn thơm, đặt lên cơm với trứng chiên."},
{ten: "Trứng chiên Thái", goc: "ไข่เจียว · Khai chiao", am_thuc: "thai", vung: "Bangkok", bua: ["sang", "trua", "toi"], loai: "kho", mo_ta: "Trứng đánh bông chiên ngập dầu phồng vàng giòn viền, ăn với cơm nóng và tương ớt sriracha."},
{ten: "Lẩu Jim Jum", goc: "จิ้มจุ่ม · Chim chum", am_thuc: "thai", vung: "Isan", bua: ["toi"], loai: "nuong", mo_ta: "Nồi đất nhỏ nước dùng sả, riềng, lá chanh, nhúng thịt, hải sản, rau, chấm sốt chua cay Isan."},
{ten: "Nam Prik Kapi", goc: "น้ำพริกกะปิ · Nam phrik kapi", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Mắm ruốc giã ớt, tỏi, chanh, chấm rau luộc, rau sống và cá bạc má chiên, bữa cơm nhà Thái."},
{ten: "Cà ri rừng Gaeng Pa", goc: "แกงป่า · Kaeng pa", am_thuc: "thai", vung: "Miền Trung Thái Lan", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Cà ri không nước cốt dừa, cay nồng với tiêu xanh, cà tím, ngải và thịt, đậm chất thôn quê."},
{ten: "Canh chua cay Tom Saap", goc: "ต้มแซ่บ · Tom saep", am_thuc: "thai", vung: "Isan", bua: ["toi"], loai: "nuoc", mo_ta: "Sườn heo hầm với sả, riềng, ớt khô, chanh và thính, chua cay xé lưỡi kiểu Isan."},
{ten: "Cổ heo nướng", goc: "คอหมูย่าง · Kho mu yang", am_thuc: "thai", vung: "Isan", bua: ["toi", "khuya"], loai: "nuong", mo_ta: "Thịt cổ heo nướng than mềm giòn mỡ, thái lát chấm sốt jaew ớt khô chua cay, ăn với xôi."},
{ten: "Bò nướng Hổ khóc", goc: "เสือร้องไห้ · Suea rong hai", am_thuc: "thai", vung: "Isan", bua: ["toi"], loai: "nuong", mo_ta: "Ức bò nướng thái mỏng chấm sốt ớt khô chua cay, tên món kể rằng hổ cũng phải khóc vì thèm."},
{ten: "Cơm trộn mắm ruốc Thái", goc: "ข้าวคลุกกะปิ · Khao khluk kapi", am_thuc: "thai", vung: "Bangkok", bua: ["trua"], loai: "kho", mo_ta: "Cơm trộn mắm ruốc ăn với thịt heo kho ngọt, xoài xanh, trứng tráng sợi, hành tím và ớt."},
{ten: "Cơm gà Khao Mok", goc: "ข้าวหมกไก่ · Khao mok kai", am_thuc: "thai", vung: "Miền Nam Thái Lan", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cơm nghệ vàng nấu cùng gà tẩm gia vị của người Thái Hồi giáo, chấm sốt bạc hà chua ngọt."},
{ten: "Miến xào Thái", goc: "ผัดวุ้นเส้น · Phat wun sen", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "kho", mo_ta: "Miến xào trứng, bắp cải, cà rốt, nấm mèo và tôm, nêm nước mắm nhẹ, mềm dai đậm đà."},
{ten: "Bánh Look Chup", goc: "ลูกชุบ · Luk chup", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Đậu xanh nặn thành trái cây tí hon, tô màu và phủ thạch bóng, đẹp đến không nỡ ăn."},
{ten: "Bánh Khanom Tuay", goc: "ขนมถ้วย · Khanom thuai", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Chén bánh hấp hai lớp, dưới ngọt lá dứa, trên nước cốt dừa mặn béo, múc từng thìa nhỏ."},
{ten: "Gỏi cá trê giòn", goc: "ยำปลาดุกฟู · Yam pla duk fu", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Thịt cá trê nướng xé tơi chiên phồng giòn như bông, ăn với gỏi xoài xanh chua cay."},
{ten: "Bí đỏ nhân flan", goc: "สังขยาฟักทอง · Sangkhaya fak thong", am_thuc: "thai", vung: "Bangkok", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Quả bí đỏ khoét ruột đổ đầy trứng, nước cốt dừa, đường thốt nốt rồi hấp, cắt múi ăn ngọt béo."},
{ten: "Gà rán Hat Yai", goc: "ไก่ทอดหาดใหญ่ · Kai thot Hat Yai", am_thuc: "thai", vung: "Hat Yai", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Gà ướp gia vị chiên giòn phủ hành phi vàng, ăn kèm xôi, món nổi tiếng của miền Nam Thái."},
{ten: "Cơm trộn Khao Yam", goc: "ข้าวยำ · Khao yam", am_thuc: "thai", vung: "Miền Nam Thái Lan", bua: ["sang", "trua"], loai: "kho", mo_ta: "Cơm trộn rau thơm thái nhỏ, dừa rang, tôm khô, bưởi, rưới nước sốt cá lên men budu."},

// Đông Nam Á khác
{ten: "Nasi goreng", goc: "", am_thuc: "dna", vung: "Indonesia", bua: ["sang", "trua", "toi"], loai: "kho", mo_ta: "Cơm chiên nước tương ngọt kecap manis với hành tím, ớt, thêm trứng ốp la và bánh phồng tôm."},
{ten: "Mie goreng", goc: "", am_thuc: "dna", vung: "Indonesia", bua: ["trua", "toi", "khuya"], loai: "kho", mo_ta: "Mì trứng xào nước tương ngọt với rau cải, gà hoặc tôm, hành phi, ngọt mặn cay đủ cả."},
{ten: "Rendang", goc: "", am_thuc: "dna", vung: "Padang", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt bò hầm nước cốt dừa và gia vị hàng giờ đến khi khô sệt đen bóng, đậm đà sâu thẳm."},
{ten: "Sate ayam", goc: "", am_thuc: "dna", vung: "Indonesia", bua: ["toi", "khuya"], loai: "nuong", mo_ta: "Xiên thịt gà nhỏ nướng than quét nước tương ngọt, chấm sốt đậu phộng sánh, ăn với cơm nắm."},
{ten: "Gado-gado", goc: "", am_thuc: "dna", vung: "Jakarta", bua: ["trua"], loai: "anvat", mo_ta: "Rau luộc, đậu hũ, tempeh, trứng và khoai tây rưới sốt đậu phộng, kèm bánh phồng tôm giòn."},
{ten: "Soto ayam", goc: "", am_thuc: "dna", vung: "Indonesia", bua: ["sang", "trua"], loai: "nuoc", mo_ta: "Canh gà vàng nghệ với miến, trứng luộc, giá và hành phi, vắt chanh thêm ớt, ấm bụng."},
{ten: "Bakso", goc: "", am_thuc: "dna", vung: "Malang", bua: ["trua", "toi", "khuya"], loai: "nuoc", mo_ta: "Bò viên to dai trong nước dùng trong, thêm mì, đậu hũ chiên, rưới tương ớt và nước tương ngọt."},
{ten: "Nasi uduk", goc: "", am_thuc: "dna", vung: "Jakarta", bua: ["sang", "trua"], loai: "kho", mo_ta: "Cơm nấu nước cốt dừa và sả thơm béo, ăn với gà chiên, tempeh, trứng và tương ớt sambal."},
{ten: "Nasi Padang", goc: "", am_thuc: "dna", vung: "Padang", bua: ["trua", "toi"], loai: "kho", mo_ta: "Đĩa cơm trắng với hàng chục món cà ri, rendang, rau xếp chồng trong tủ kính, chọn món nào trả món đó."},
{ten: "Ayam penyet", goc: "", am_thuc: "dna", vung: "Surabaya", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà chiên được dần dập trên cối đá cùng tương ớt sambal cay xé, ăn với cơm, đậu hũ và rau."},
{ten: "Ayam betutu", goc: "", am_thuc: "dna", vung: "Bali", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà nhồi hỗn hợp gia vị Bali, gói lá chuối nướng hoặc hầm lâu, thịt mềm thấm cay thơm."},
{ten: "Babi guling", goc: "", am_thuc: "dna", vung: "Bali", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Heo sữa nhồi gia vị quay quanh than, da giòn như bánh đa, món lễ hội của người Bali."},
{ten: "Pempek", goc: "", am_thuc: "dna", vung: "Palembang", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Chả cá dai nhồi trứng chiên vàng, chấm nước sốt cuko chua cay ngọt đen sẫm, đặc sản Palembang."},
{ten: "Martabak manis", goc: "", am_thuc: "dna", vung: "Indonesia", bua: ["toi", "khuya"], loai: "trangmieng", mo_ta: "Bánh xốp dày như bánh rán khổng lồ, phết bơ, sô cô la, phô mai, đậu phộng rồi gập đôi."},
{ten: "Martabak telur", goc: "", am_thuc: "dna", vung: "Indonesia", bua: ["toi", "khuya"], loai: "anvat", mo_ta: "Bánh bột mỏng kẹp trứng, thịt băm, hành lá chiên giòn, cắt ô vuông ăn với dưa chua."},
{ten: "Klepon", goc: "", am_thuc: "dna", vung: "Java", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Viên nếp xanh lá dứa lăn dừa nạo, cắn vào là đường thốt nốt lỏng phụt ra ngọt lịm."},
{ten: "Tempeh", goc: "", am_thuc: "dna", vung: "Java", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh đậu nành lên men nén chặt, chiên giòn bùi thơm, ăn kèm cơm và tương ớt sambal."},
{ten: "Rawon", goc: "", am_thuc: "dna", vung: "Surabaya", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Canh bò nước đen từ hạt keluak, vị đậm bùi lạ, ăn với cơm, giá sống và trứng muối."},
{ten: "Gudeg", goc: "", am_thuc: "dna", vung: "Yogyakarta", bua: ["sang", "trua"], loai: "kho", mo_ta: "Mít non hầm đường thốt nốt và nước cốt dừa nhiều giờ, ngọt dịu, ăn với cơm, gà và trứng."},
{ten: "Sop buntut", goc: "", am_thuc: "dna", vung: "Jakarta", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Đuôi bò hầm mềm với cà rốt, khoai tây, cà chua trong nước dùng trong thơm hành phi."},
{ten: "Es teler", goc: "", am_thuc: "dna", vung: "Jakarta", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bơ, mít, cơm dừa non trong nước cốt dừa, sữa đặc và đá bào, cốc chè trái cây kiểu Indonesia."},
{ten: "Pisang goreng", goc: "", am_thuc: "dna", vung: "Indonesia", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Chuối tẩm bột chiên vàng giòn, ngọt mềm bên trong, món ăn xế đi cùng ly trà nóng."},
{ten: "Siomay Bandung", goc: "", am_thuc: "dna", vung: "Bandung", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Chả cá hấp, bắp cải, khoai tây, trứng và đậu hũ, rưới sốt đậu phộng và nước tương ngọt."},
{ten: "Nasi lemak", goc: "", am_thuc: "dna", vung: "Malaysia", bua: ["sang", "trua"], loai: "kho", mo_ta: "Cơm dừa thơm lá dứa với tương ớt sambal, cá cơm chiên, đậu phộng, trứng và dưa leo, gói lá chuối."},
{ten: "Roti canai", goc: "", am_thuc: "dna", vung: "Malaysia", bua: ["sang", "toi", "khuya"], loai: "anvat", mo_ta: "Bánh bột mì quay mỏng nhiều lớp áp chảo giòn xốp, xé chấm cà ri đậu hoặc cà ri gà."},
{ten: "Asam laksa", goc: "", am_thuc: "dna", vung: "Penang", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Bún sợi to trong nước dùng cá thu chua me cay, thêm dứa, bạc hà, hành, rưới mắm tôm sệt."},
{ten: "Curry laksa", goc: "", am_thuc: "dna", vung: "Kuala Lumpur", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Bún và mì trong nước cà ri dừa cay béo, đậu hũ chiên, tôm, nghêu và giá, ăn là ra mồ hôi."},
{ten: "Char kway teow", goc: "炒粿條", am_thuc: "dna", vung: "Penang", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh phở dẹt xào lửa lớn với tôm, sò huyết, lạp xưởng, giá và trứng, thơm mùi khói chảo."},
{ten: "Nasi kandar", goc: "", am_thuc: "dna", vung: "Penang", bua: ["trua", "toi", "khuya"], loai: "kho", mo_ta: "Cơm trắng chan nhiều loại cà ri trộn lẫn, kèm gà chiên, cá và trứng, quán mở suốt đêm."},
{ten: "Bak kut teh", goc: "肉骨茶", am_thuc: "dna", vung: "Klang", bua: ["sang", "trua"], loai: "nuoc", mo_ta: "Sườn heo hầm thảo mộc, tỏi và tiêu, nước dùng nâu thơm, ăn với cơm, quẩy và trà nóng."},
{ten: "Roti john", goc: "", am_thuc: "dna", vung: "Singapore", bua: ["toi", "khuya"], loai: "anvat", mo_ta: "Ổ bánh mì dài phết trứng đánh với thịt băm hành tây, áp chảo, rưới tương ớt và mayonnaise."},
{ten: "Cendol", goc: "", am_thuc: "dna", vung: "Melaka", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Sợi bột gạo xanh lá dứa trong nước cốt dừa, đường thốt nốt và đá bào, mát rượi ngày oi."},
{ten: "Teh tarik", goc: "", am_thuc: "dna", vung: "Malaysia", bua: ["sang", "trua", "toi"], loai: "douong", mo_ta: "Trà sữa được kéo qua lại giữa hai ca cho nổi bọt mịn, ngọt béo, uống cùng roti canai."},
{ten: "Apam balik", goc: "", am_thuc: "dna", vung: "Malaysia", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh bột xốp nướng chảo rắc đậu phộng giã, đường và bắp ngọt, gập đôi, giòn rìa mềm giữa."},
{ten: "Ais kacang", goc: "", am_thuc: "dna", vung: "Malaysia", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Núi đá bào rưới siro đỏ và sữa đặc, bên dưới là đậu đỏ, bắp ngọt, thạch, mát lạnh nhiều màu."},
{ten: "Nasi kerabu", goc: "", am_thuc: "dna", vung: "Kelantan", bua: ["sang", "trua"], loai: "kho", mo_ta: "Cơm xanh nhuộm hoa đậu biếc, trộn rau thơm thái nhỏ, dừa rang, ăn với cá hoặc gà nướng."},
{ten: "Rojak", goc: "", am_thuc: "dna", vung: "Malaysia", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Dứa, dưa leo, củ đậu, xoài xanh và quẩy trộn sốt mắm tôm đặc ngọt, rắc đậu phộng giã."},
{ten: "Ikan bakar", goc: "", am_thuc: "dna", vung: "Malaysia", bua: ["toi"], loai: "nuong", mo_ta: "Cá phết tương ớt sambal gói lá chuối nướng than, thịt thơm cay, ăn với cơm và hành tím."},
{ten: "Pan mee", goc: "板面", am_thuc: "dna", vung: "Kuala Lumpur", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Mì bột mì cán tay trong nước dùng cá cơm với thịt băm, nấm, rau ngót và cá cơm chiên giòn."},
{ten: "Asam pedas", goc: "", am_thuc: "dna", vung: "Melaka", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Cá nấu nước sốt me chua cay đỏ au với đậu bắp, cà chua và lá rau răm, ăn với cơm trắng."},
{ten: "Mee rebus", goc: "", am_thuc: "dna", vung: "Johor", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Mì vàng chan nước sốt khoai lang sánh ngọt, thêm trứng, đậu hũ, giá và vắt quả tắc."},
{ten: "Otak-otak", goc: "", am_thuc: "dna", vung: "Muar", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Chả cá trộn nước cốt dừa và cà ri đỏ, gói lá dừa nướng than, mềm cay thơm khói."},
{ten: "Cơm gà Hải Nam", goc: "海南鸡饭 · Hainanese chicken rice", am_thuc: "dna", vung: "Singapore", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà luộc da bóng mượt trên cơm nấu mỡ gà, gừng, lá dứa, chấm tương ớt, gừng băm và xì dầu đen."},
{ten: "Cua sốt ớt Singapore", goc: "Chilli crab", am_thuc: "dna", vung: "Singapore", bua: ["toi"], loai: "kho", mo_ta: "Cua bùn to trong sốt cà chua ớt ngọt cay sánh với trứng, chấm bánh mì chiên vào sốt."},
{ten: "Bak chor mee", goc: "肉脞面", am_thuc: "dna", vung: "Singapore", bua: ["sang", "trua"], loai: "kho", mo_ta: "Mì trộn giấm đen, tương ớt, thịt băm, cá viên, gan và nấm, chua cay đậm đà."},
{ten: "Bánh mì kaya", goc: "Kaya toast", am_thuc: "dna", vung: "Singapore", bua: ["sang"], loai: "anvat", mo_ta: "Bánh mì nướng giòn kẹp mứt kaya trứng dừa và lát bơ lạnh, chấm trứng lòng đào với xì dầu."},
{ten: "Hokkien prawn mee", goc: "福建虾面 · Hokkien hae mee", am_thuc: "dna", vung: "Singapore", bua: ["trua", "toi"], loai: "kho", mo_ta: "Mì vàng và bún xào trong nước dùng tôm đậm đà, tôm, mực, ăn kèm tương ớt và vắt tắc."},
{ten: "Cà ri đầu cá", goc: "Fish head curry", am_thuc: "dna", vung: "Singapore", bua: ["toi"], loai: "nuoc", mo_ta: "Đầu cá hồng to hầm trong cà ri chua cay với đậu bắp, cà tím, món Ấn Hoa lai của Singapore."},
{ten: "Chwee kueh", goc: "水粿", am_thuc: "dna", vung: "Singapore", bua: ["sang"], loai: "anvat", mo_ta: "Bánh gạo hấp trong chén nhỏ phủ củ cải muối xào dầu, mềm mịn mặn thơm, giống bánh bèo."},
{ten: "Yu sheng", goc: "鱼生 · Yúshēng", am_thuc: "dna", vung: "Singapore", bua: ["toi"], loai: "anvat", mo_ta: "Gỏi cá sống với rau củ thái sợi, cả bàn cùng hất cao bằng đũa để cầu may ngày Tết."},
{ten: "Adobo", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà hoặc heo kho với giấm, xì dầu, tỏi, lá nguyệt quế và tiêu, chua mặn đậm đà, món quốc hồn."},
{ten: "Sinigang", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Canh chua me với thịt heo hoặc tôm, rau muống, củ cải và đậu bắp, chua thanh ấm lòng."},
{ten: "Lechon", goc: "", am_thuc: "dna", vung: "Cebu", bua: ["toi"], loai: "nuong", mo_ta: "Heo sữa quay nguyên con trên than, da vàng giòn rụm, thịt thơm sả, trung tâm của mọi bữa tiệc."},
{ten: "Sisig", goc: "", am_thuc: "dna", vung: "Pampanga", bua: ["toi", "khuya"], loai: "kho", mo_ta: "Thịt mặt heo băm nhỏ trên đĩa gang nóng xèo xèo, thêm hành, ớt, trứng và vắt tắc."},
{ten: "Kare-kare", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Đuôi bò hầm sốt đậu phộng sánh với cà tím, đậu đũa, cải, ăn kèm mắm tôm bagoong."},
{ten: "Pancit canton", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["trua", "toi"], loai: "kho", mo_ta: "Mì trứng xào thịt, tôm và rau, vắt tắc, món ăn mừng sinh nhật cầu sống lâu."},
{ten: "Halo-halo", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Đá bào trộn đậu ngọt, thạch, mứt khoai môn tím, bánh flan và kem, xáo đều lên mà ăn."},
{ten: "Bibingka", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["sang", "toi"], loai: "trangmieng", mo_ta: "Bánh gạo nướng trong lá chuối với trứng muối và dừa nạo, mềm thơm, món của mùa Giáng sinh."},
{ten: "Ube halaya", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Mứt khoai mỡ tím nấu với sữa và bơ, sánh dẻo màu tím lộng lẫy, ngọt béo thơm bùi."},
{ten: "Tapsilog", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["sang"], loai: "kho", mo_ta: "Thịt bò khô ướp ngọt áp chảo, cơm chiên tỏi và trứng ốp la, bữa sáng chuẩn kiểu Philippines."},
{ten: "Arroz caldo", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["sang", "toi"], loai: "nuoc", mo_ta: "Cháo gạo nấu gà và gừng, rắc tỏi phi và hành, thêm trứng luộc, ấm bụng ngày mưa."},
{ten: "Bulalo", goc: "", am_thuc: "dna", vung: "Batangas", bua: ["toi"], loai: "nuoc", mo_ta: "Bắp bò và xương ống nhiều tủy hầm với bắp ngô và cải, nước dùng trong ngọt béo."},
{ten: "Kinilaw", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Cá tươi thái miếng ngâm giấm dừa với gừng, hành, ớt, chua thanh như gỏi biển."},
{ten: "Gà nướng Inasal", goc: "Chicken inasal", am_thuc: "dna", vung: "Bacolod", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Gà ướp sả, giấm, tắc nướng than phết dầu hạt điều màu cam, ăn với cơm và nước chấm."},
{ten: "Turon", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Chuối và mít cuộn bánh tráng chiên giòn, phủ đường thắng caramel bóng, món ăn vặt buổi chiều."},
{ten: "Ensaymada", goc: "", am_thuc: "dna", vung: "Philippines", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Bánh mì xoắn mềm xốp phết bơ, rắc đường và phô mai bào, ngọt mặn hài hòa."},
{ten: "Khao piak sen", goc: "ເຂົ້າປຽກເສັ້ນ", am_thuc: "dna", vung: "Lào", bua: ["sang", "trua", "toi"], loai: "nuoc", mo_ta: "Sợi bánh canh bột gạo và bột năng trong nước dùng gà sánh nhẹ, thêm tỏi phi, rau thơm, chanh."},
{ten: "Or lam", goc: "ເອາະຫຼາມ", am_thuc: "dna", vung: "Luang Prabang", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Món hầm với cà tím, rau rừng, thịt trâu khô và gỗ sakhan cay tê, đặc sản cố đô Luang Prabang."},
{ten: "Mok pa", goc: "ໝົກປາ", am_thuc: "dna", vung: "Lào", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cá trộn sả, thì là, ớt gói lá chuối hấp chín, mở lá ra thơm lừng, ăn với xôi."},
{ten: "Khao jee pâté", goc: "ເຂົ້າຈີ່ປາເຕ້", am_thuc: "dna", vung: "Vientiane", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Bánh mì giòn kẹp pate, thịt nguội, đồ chua và rau, người anh em của bánh mì Việt bên Lào."},
{ten: "Khao poon", goc: "ເຂົ້າປຸ້ນ", am_thuc: "dna", vung: "Lào", bua: ["sang", "trua"], loai: "nuoc", mo_ta: "Bún gạo chan nước dùng cá hoặc gà nấu nước cốt dừa cay nhẹ, ăn với rau sống đầy rổ."},
{ten: "Amok cá", goc: "អាម៉ុកត្រី · Amok trey", am_thuc: "dna", vung: "Campuchia", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cá trộn gia vị kroeung và nước cốt dừa hấp trong chén lá chuối, mềm mịn như bánh flan mặn."},
{ten: "Num banh chok", goc: "នំបញ្ចុក", am_thuc: "dna", vung: "Campuchia", bua: ["sang"], loai: "nuoc", mo_ta: "Bún gạo tươi chan nước cà ri cá xanh nhạt thơm sả, ăn kèm rau sống, món sáng của người Khmer."},
{ten: "Bai sach chrouk", goc: "បាយសាច់ជ្រូក", am_thuc: "dna", vung: "Campuchia", bua: ["sang"], loai: "kho", mo_ta: "Thịt heo ướp nước cốt dừa nướng than đặt trên cơm tấm, kèm đồ chua và bát canh nhỏ."},
{ten: "Samlor korko", goc: "សម្លកកូរ", am_thuc: "dna", vung: "Campuchia", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Canh khuấy nhiều loại rau củ với cá hoặc thịt, gạo rang và mắm prahok, đậm đà thôn quê."},
{ten: "Cua tiêu xanh Kampot", goc: "ក្តាមឆាម្រេចខ្ចី · Kdam chha mrech kchey", am_thuc: "dna", vung: "Kep", bua: ["toi"], loai: "kho", mo_ta: "Cua biển xào với chùm tiêu xanh Kampot tươi, cay thơm nồng, ăn bên bờ biển Kep."},
{ten: "Prahok ktis", goc: "ប្រហុកខ្ទិះ", am_thuc: "dna", vung: "Campuchia", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Mắm prahok nấu với thịt băm và nước cốt dừa thành sốt sệt, chấm rau sống và cà tím."},
{ten: "Mohinga", goc: "မုန့်ဟင်းခါး · Mont hin gar", am_thuc: "dna", vung: "Myanmar", bua: ["sang"], loai: "nuoc", mo_ta: "Bún gạo trong nước dùng cá sả và thân chuối, thêm bánh chiên giòn và trứng, món sáng quốc dân."},
{ten: "Gỏi lá trà Lahpet", goc: "လက်ဖက်သုပ် · Lahpet thoke", am_thuc: "dna", vung: "Myanmar", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Lá trà lên men trộn đậu chiên giòn, mè, tôm khô, cà chua, dầu đậu phộng, vừa chát vừa bùi."},
{ten: "Mì Shan", goc: "ရှမ်းခေါက်ဆွဲ · Shan khauk swe", am_thuc: "dna", vung: "Myanmar", bua: ["sang", "trua", "toi"], loai: "kho", mo_ta: "Bún gạo dẹt trộn sốt cà chua thịt gà hoặc heo, rắc đậu phộng, ăn kèm dưa cải muối."},
{ten: "Ohn no khao swe", goc: "အုန်းနို့ခေါက်ဆွဲ · Ohn no khauk swe", am_thuc: "dna", vung: "Myanmar", bua: ["sang", "trua"], loai: "nuoc", mo_ta: "Mì trứng trong nước dùng gà nấu cốt dừa sánh béo, thêm trứng luộc, hành tím và chanh."},

// Ấn Độ và Nam Á
{ten: "Gà bơ Ấn Độ", goc: "मुर्ग़ मक्खनी · Murgh makhani", am_thuc: "an", vung: "Delhi", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà nướng tandoor om trong sốt cà chua, bơ và kem sánh mịn màu cam, chấm bánh naan là hết sạch."},
{ten: "Gà nướng Tandoori", goc: "तंदूरी मुर्ग़ · Tandoori murgh", am_thuc: "an", vung: "Punjab", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Gà ướp sữa chua và gia vị đỏ rực nướng trong lò đất tandoor, cháy cạnh thơm khói, vắt chanh hành sống."},
{ten: "Cơm Biryani Hyderabad", goc: "हैदराबादी बिरयानी · Hyderabadi biryani", am_thuc: "an", vung: "Hyderabad", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cơm gạo basmati hạt dài xếp lớp với thịt ướp, nghệ tây, hành phi, đậy kín nấu chín hơi thơm ngào ngạt."},
{ten: "Cà ri cừu Rogan josh", goc: "रोगन जोश · Rogan josh", am_thuc: "an", vung: "Kashmir", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt cừu hầm sốt đỏ từ ớt Kashmir, sữa chua và gia vị ấm, màu đẹp mà cay dịu, ăn với cơm."},
{ten: "Palak paneer", goc: "पालक पनीर", am_thuc: "an", vung: "Punjab", bua: ["trua", "toi"], loai: "kho", mo_ta: "Phô mai paneer cắt khối trong sốt rau bina xay mịn xanh mướt, thơm tỏi gừng, béo mà thanh."},
{ten: "Paneer tikka", goc: "पनीर टिक्का", am_thuc: "an", vung: "Punjab", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Khối phô mai paneer ướp sữa chua gia vị xiên cùng ớt chuông, hành tây, nướng cháy cạnh thơm lừng."},
{ten: "Dal makhani", goc: "दाल मखनी", am_thuc: "an", vung: "Punjab", bua: ["trua", "toi"], loai: "kho", mo_ta: "Đậu lăng đen và đậu đỏ hầm qua đêm với bơ và kem, sánh mượt béo ngậy, chấm naan hay ăn cơm."},
{ten: "Chole bhature", goc: "छोले भटूरे", am_thuc: "an", vung: "Delhi", bua: ["sang", "trua"], loai: "kho", mo_ta: "Đậu gà sốt cay đậm đà ăn kèm bánh bhature chiên phồng to như quả bóng, bữa sáng chắc bụng."},
{ten: "Aloo gobi", goc: "आलू गोभी", am_thuc: "an", vung: "Punjab", bua: ["trua", "toi"], loai: "kho", mo_ta: "Khoai tây và súp lơ xào khô với nghệ, thì là, gừng, vàng ươm thơm phức, món chay nhà làm."},
{ten: "Samosa", goc: "समोसा", am_thuc: "an", vung: "Ấn Độ", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Vỏ bột chiên giòn hình tam giác nhân khoai tây, đậu Hà Lan và gia vị, chấm tương me hay sốt bạc hà."},
{ten: "Pani puri", goc: "पानी पूरी", am_thuc: "an", vung: "Mumbai", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Vỏ bánh rỗng giòn đục lỗ, nhồi khoai tây, đậu gà, rót nước me bạc hà chua cay rồi bỏ trọn vào miệng."},
{ten: "Pav bhaji", goc: "पाव भाजी", am_thuc: "an", vung: "Mumbai", bua: ["trua", "toi", "khuya"], loai: "kho", mo_ta: "Rau củ nghiền nấu gia vị sánh đỏ với cục bơ to, chấm bánh mì mềm nướng bơ, món đường phố Mumbai."},
{ten: "Vada pav", goc: "वडा पाव", am_thuc: "an", vung: "Mumbai", bua: ["sang", "toi"], loai: "anvat", mo_ta: "Viên khoai tây tẩm bột đậu chiên giòn kẹp trong bánh mì mềm với tương ớt tỏi, burger của Mumbai."},
{ten: "Masala dosa", goc: "ಮಸಾಲೆ ದೋಸೆ · Masale dose", am_thuc: "an", vung: "Karnataka", bua: ["sang", "trua"], loai: "kho", mo_ta: "Bánh crepe gạo đậu lên men mỏng giòn cuộn khoai tây xào gia vị, chấm sambar và tương dừa."},
{ten: "Idli sambar", goc: "இட்லி சாம்பார்", am_thuc: "an", vung: "Tamil Nadu", bua: ["sang"], loai: "kho", mo_ta: "Bánh gạo hấp trắng xốp như mây, chấm canh đậu lăng sambar chua nhẹ và tương dừa, bữa sáng miền Nam Ấn."},
{ten: "Medu vada", goc: "மெது வடை · Medu vadai", am_thuc: "an", vung: "Tamil Nadu", bua: ["sang"], loai: "anvat", mo_ta: "Bánh đậu xay chiên hình chiếc nhẫn, giòn ngoài mềm trong, nhúng sambar nóng hổi là tuyệt."},
{ten: "Uttapam", goc: "ஊத்தப்பம் · Uthappam", am_thuc: "an", vung: "Tamil Nadu", bua: ["sang"], loai: "kho", mo_ta: "Bánh bột gạo lên men dày như pizza nhỏ, rắc hành, cà chua, ớt xanh, chấm tương dừa."},
{ten: "Cà ri cá Kerala", goc: "മീൻ കറി · Meen curry", am_thuc: "an", vung: "Kerala", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Cá nấu với nước cốt dừa, lá cà ri và me, chua cay béo nhẹ màu đỏ cam, ăn với cơm đỏ."},
{ten: "Chicken 65", goc: "", am_thuc: "an", vung: "Chennai", bua: ["toi", "khuya"], loai: "anvat", mo_ta: "Gà chiên giòn ướp ớt đỏ, gừng tỏi, đảo với lá cà ri và ớt xanh, cay thơm, món khai vị nhâm nhi."},
{ten: "Gà Chettinad", goc: "செட்டிநாடு கோழி · Chettinad kozhi", am_thuc: "an", vung: "Tamil Nadu", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà nấu với tiêu đen, hoa hồi, dừa rang và hàng chục gia vị, cay nồng thơm sâu đặc trưng Chettinad."},
{ten: "Vindaloo", goc: "", am_thuc: "an", vung: "Goa", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt heo hầm giấm, tỏi và ớt đỏ khô, chua cay nóng bỏng, dấu tích người Bồ Đào Nha ở Goa."},
{ten: "Malai kofta", goc: "मलाई कोफ़्ता", am_thuc: "an", vung: "Delhi", bua: ["trua", "toi"], loai: "kho", mo_ta: "Viên khoai tây phô mai chiên vàng ngâm trong sốt kem hạt điều béo ngọt, món chay sang trọng."},
{ten: "Naan bơ tỏi", goc: "गार्लिक नान · Garlic naan", am_thuc: "an", vung: "Punjab", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh naan nướng áp vách lò tandoor phồng cháy chấm, phết bơ tỏi và rau mùi, xé chấm cà ri."},
{ten: "Aloo paratha", goc: "आलू पराठा", am_thuc: "an", vung: "Punjab", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Bánh mì dẹt nhân khoai tây gia vị áp chảo với bơ ghee, ăn kèm sữa chua và dưa muối cay."},
{ten: "Thali", goc: "थाली", am_thuc: "an", vung: "Rajasthan", bua: ["trua", "toi"], loai: "kho", mo_ta: "Mâm tròn bày nhiều chén nhỏ cà ri, đậu, rau, sữa chua, cơm và bánh mì, nếm đủ mọi vị một lúc."},
{ten: "Cà ri Korma", goc: "कोरमा · Korma", am_thuc: "an", vung: "Lucknow", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt hầm sốt sữa chua, kem và hạt điều xay, nhẹ cay thơm béo, hợp với người mới ăn cà ri."},
{ten: "Haleem", goc: "حلیم", am_thuc: "an", vung: "Hyderabad", bua: ["toi"], loai: "nuoc", mo_ta: "Lúa mì, đậu và thịt hầm nhiều giờ đến sánh mịn như cháo đặc, rắc hành phi, món của tháng Ramadan."},
{ten: "Seekh kebab", goc: "सीख़ कबाब", am_thuc: "an", vung: "Delhi", bua: ["toi", "khuya"], loai: "nuong", mo_ta: "Thịt cừu băm trộn gia vị nặn quanh xiên sắt nướng lò tandoor, mềm ẩm cay thơm, cuốn bánh mì."},
{ten: "Galouti kebab", goc: "गलौटी कबाब", am_thuc: "an", vung: "Lucknow", bua: ["toi"], loai: "nuong", mo_ta: "Miếng thịt băm mịn ướp hơn chục gia vị áp chảo, mềm tan trong miệng, món của các vua chúa Lucknow."},
{ten: "Dhokla", goc: "ઢોકળા", am_thuc: "an", vung: "Gujarat", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Bánh bột đậu gà hấp xốp vàng, rưới dầu hạt mù tạt và lá cà ri, chua ngọt mềm như bông."},
{ten: "Pakora", goc: "पकोड़ा", am_thuc: "an", vung: "Ấn Độ", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Hành tây, khoai, rau tẩm bột đậu gà chiên giòn, ăn với tương bạc hà và chén trà sữa ngày mưa."},
{ten: "Bhel puri", goc: "भेल पुरी", am_thuc: "an", vung: "Mumbai", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Gạo phồng trộn sợi bột chiên, khoai, hành, cà chua, tương me và bạc hà, giòn chua ngọt bãi biển."},
{ten: "Gulab jamun", goc: "गुलाब जामुन", am_thuc: "an", vung: "Ấn Độ", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Viên sữa chiên nâu ngâm siro hoa hồng bạch đậu khấu, mềm xốp ngọt lịm, ăn ấm càng ngon."},
{ten: "Rasgulla", goc: "রসগোল্লা · Rosogolla", am_thuc: "an", vung: "Kolkata", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Viên phô mai tươi trắng mềm xốp ngâm nước đường thanh, bóp nhẹ là nước đường chảy ra."},
{ten: "Jalebi", goc: "जलेबी", am_thuc: "an", vung: "Ấn Độ", bua: ["sang", "toi"], loai: "trangmieng", mo_ta: "Bột chiên xoắn ốc vàng cam giòn rụm ngâm siro đường, ngọt lịm, ăn nóng với sữa hoặc rabri."},
{ten: "Kheer", goc: "खीर", am_thuc: "an", vung: "Ấn Độ", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Gạo nấu sữa sánh với đường, bạch đậu khấu, nghệ tây, rắc hạnh nhân và hồ trăn, ngọt dịu thơm."},
{ten: "Gajar halwa", goc: "गाजर का हलवा · Gajar ka halwa", am_thuc: "an", vung: "Punjab", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Cà rốt bào nấu chậm với sữa, bơ ghee và đường, rắc hạt điều, món ngọt ấm của mùa đông Bắc Ấn."},
{ten: "Kulfi", goc: "क़ुल्फ़ी", am_thuc: "an", vung: "Delhi", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Kem sữa cô đặc đông trong khuôn nón, dày đặc hơn kem thường, vị hồ trăn và bạch đậu khấu."},
{ten: "Lassi xoài", goc: "आम लस्सी · Aam lassi", am_thuc: "an", vung: "Punjab", bua: ["trua", "toi"], loai: "douong", mo_ta: "Sữa chua xay với xoài chín và chút bạch đậu khấu, sánh mịn mát lạnh, dập lửa sau món cay."},
{ten: "Trà masala", goc: "मसाला चाय · Masala chai", am_thuc: "an", vung: "Ấn Độ", bua: ["sang", "trua", "toi"], loai: "douong", mo_ta: "Trà đen đun với sữa, gừng, quế, bạch đậu khấu, rót từ trên cao cho nổi bọt, ngọt ấm thơm nồng."},
{ten: "Mishti doi", goc: "মিষ্টি দই", am_thuc: "an", vung: "Kolkata", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Sữa chua ngọt màu nâu caramel lên men trong niêu đất, đặc mịn thơm đường thốt nốt."},
{ten: "Rajma chawal", goc: "राजमा चावल", am_thuc: "an", vung: "Punjab", bua: ["trua"], loai: "kho", mo_ta: "Đậu đỏ hầm sốt cà chua hành gừng sánh đậm, chan lên cơm trắng, bữa trưa Chủ nhật của người Punjab."},
{ten: "Poha", goc: "पोहा", am_thuc: "an", vung: "Indore", bua: ["sang"], loai: "kho", mo_ta: "Gạo dẹt xào nghệ, hạt mù tạt, lá cà ri, đậu phộng và hành, vắt chanh, bữa sáng nhẹ nhàng."},
{ten: "Pongal", goc: "பொங்கல்", am_thuc: "an", vung: "Tamil Nadu", bua: ["sang"], loai: "kho", mo_ta: "Gạo và đậu xanh nấu nhừ với bơ ghee, tiêu, thì là và hạt điều, mềm béo, ăn kèm sambar."},
{ten: "Nihari", goc: "نہاری", am_thuc: "an", vung: "Lahore", bua: ["sang"], loai: "nuoc", mo_ta: "Bắp bò hầm qua đêm trong nước sốt gia vị sánh đặc, ăn sáng với bánh naan, gừng sợi và chanh."},
{ten: "Gà Karahi", goc: "چکن کڑاہی · Chicken karahi", am_thuc: "an", vung: "Pakistan", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà nấu trong chảo sâu với cà chua, gừng, ớt xanh, sốt sệt cay thơm, xé naan mà chấm."},
{ten: "Chapli kebab", goc: "چپلی کباب", am_thuc: "an", vung: "Peshawar", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Thịt bò băm dẹt to như dép trộn hạt lựu, rau mùi, ớt, chiên giòn viền, đặc sản Peshawar."},
{ten: "Kottu roti", goc: "කොත්තු රොටි", am_thuc: "an", vung: "Sri Lanka", bua: ["toi", "khuya"], loai: "kho", mo_ta: "Bánh roti băm nhỏ xào trên chảo phẳng với trứng, rau và cà ri, tiếng dao gõ lách cách vang cả phố."},
{ten: "Egg hopper", goc: "බිත්තර ආප්ප · Biththara appa", am_thuc: "an", vung: "Sri Lanka", bua: ["sang", "toi"], loai: "kho", mo_ta: "Bánh bột gạo dừa lên men hình bát, viền mỏng giòn, lòng mềm ôm quả trứng, chấm sambol hành ớt."},
{ten: "Lamprais", goc: "", am_thuc: "an", vung: "Colombo", bua: ["trua"], loai: "kho", mo_ta: "Cơm nấu nước dùng cùng cà ri thịt, chả viên, trứng và sambol gói lá chuối nướng, món lai Hà Lan."},
{ten: "Momo", goc: "मःमः", am_thuc: "an", vung: "Nepal", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Bánh bao nhỏ nhân thịt hoặc rau hấp chín, chấm tương cà chua ớt mè cay, món ăn vặt số một Kathmandu."},
{ten: "Dal bhat", goc: "दाल भात", am_thuc: "an", vung: "Nepal", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cơm trắng, súp đậu lăng, cà ri rau và dưa muối, bữa ăn hằng ngày của người Nepal, được thêm thoải mái."},
{ten: "Thukpa", goc: "ཐུག་པ་", am_thuc: "an", vung: "Tây Tạng", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Mì trong nước dùng nóng với thịt và rau, ấm áp vùng núi cao Tây Tạng và Himalaya."},
{ten: "Cá mòi dầu sốt mù tạt", goc: "সর্ষে ইলিশ · Shorshe ilish", am_thuc: "an", vung: "Bangladesh", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cá mòi dầu hilsa nấu sốt hạt mù tạt xay và ớt xanh, béo thơm hăng nhẹ, ăn với cơm trắng."},
{ten: "Mas huni", goc: "", am_thuc: "an", vung: "Maldives", bua: ["sang"], loai: "anvat", mo_ta: "Cá ngừ xé trộn dừa nạo, hành, ớt và chanh, ăn với bánh roshi mỏng, bữa sáng của người Maldives."},
{ten: "Kabuli pulao", goc: "قابلی پلو · Qabili palaw", am_thuc: "an", vung: "Afghanistan", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cơm hạt dài nấu với thịt cừu, phủ cà rốt thái sợi và nho khô ngọt, món quốc hồn của Afghanistan."},

// Trung Đông và Bắc Phi
{ten: "Hummus", goc: "حمص", am_thuc: "trungdong", vung: "Liban", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Đậu gà nghiền mịn với tahini, chanh, tỏi, rưới dầu ô liu và ớt bột, quệt bánh pita là ngon."},
{ten: "Falafel", goc: "فلافل", am_thuc: "trungdong", vung: "Liban", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Viên đậu gà xay trộn rau mùi chiên giòn xanh bên trong, kẹp bánh pita với sốt tahini và rau."},
{ten: "Shawarma", goc: "شاورما", am_thuc: "trungdong", vung: "Liban", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Thịt gà hoặc bò ướp gia vị quay trên trục đứng, lạng mỏng cuộn bánh mì dẹt với sốt tỏi và dưa chua."},
{ten: "Tabbouleh", goc: "تبولة", am_thuc: "trungdong", vung: "Liban", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Rau mùi tây thái nhuyễn trộn lúa mì bulgur, cà chua, bạc hà, chanh và dầu ô liu, xanh mát tươi rói."},
{ten: "Fattoush", goc: "فتوش", am_thuc: "trungdong", vung: "Liban", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Salad rau, dưa leo, cà chua trộn bánh pita nướng giòn và bột sumac chua đỏ, giòn rụm mát lành."},
{ten: "Baba ghanoush", goc: "بابا غنوج", am_thuc: "trungdong", vung: "Syria", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Cà tím nướng cháy vỏ nghiền với tahini, tỏi và chanh, thơm khói béo mịn, chấm bánh mì."},
{ten: "Muhammara", goc: "محمرة", am_thuc: "trungdong", vung: "Aleppo", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Ớt đỏ nướng xay với óc chó, vụn bánh mì và siro lựu, cay ngọt bùi, món chấm của Aleppo."},
{ten: "Manakish", goc: "مناقيش", am_thuc: "trungdong", vung: "Liban", bua: ["sang"], loai: "anvat", mo_ta: "Bánh mì dẹt nướng phủ lá thơm za'atar và dầu ô liu, bữa sáng của người Liban cùng ly trà."},
{ten: "Kibbeh", goc: "كبة", am_thuc: "trungdong", vung: "Liban", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Vỏ lúa mì bulgur trộn thịt băm, nhân thịt hành hạt thông, chiên giòn hình quả trám."},
{ten: "Gà xiên Shish tawook", goc: "شيش طاووق · Shish tawook", am_thuc: "trungdong", vung: "Liban", bua: ["toi"], loai: "nuong", mo_ta: "Gà ướp sữa chua, tỏi và chanh xiên que nướng than, chấm sốt tỏi toum trắng mịn."},
{ten: "Labneh", goc: "لبنة", am_thuc: "trungdong", vung: "Liban", bua: ["sang"], loai: "anvat", mo_ta: "Sữa chua lọc đặc như phô mai kem, rưới dầu ô liu, rắc za'atar, quệt bánh mì buổi sáng."},
{ten: "Fatteh", goc: "فتة", am_thuc: "trungdong", vung: "Syria", bua: ["sang", "trua"], loai: "kho", mo_ta: "Bánh mì nướng giòn lót đáy, phủ đậu gà, sữa chua tỏi và tahini, rắc hạt thông rang bơ."},
{ten: "Mansaf", goc: "منسف", am_thuc: "trungdong", vung: "Jordan", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt cừu nấu sốt sữa chua khô jameed, đặt trên cơm và bánh mì mỏng, món quốc hồn của Jordan."},
{ten: "Maqluba", goc: "مقلوبة", am_thuc: "trungdong", vung: "Palestine", bua: ["trua", "toi"], loai: "kho", mo_ta: "Nồi cơm nấu với gà, cà tím chiên, súp lơ rồi úp ngược ra mâm, tên món nghĩa là lộn ngược."},
{ten: "Musakhan", goc: "مسخن", am_thuc: "trungdong", vung: "Palestine", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh mì taboon phủ hành tây xào sumac tím và gà quay, rắc hạt thông, ăn bằng tay."},
{ten: "Knafeh", goc: "كنافة", am_thuc: "trungdong", vung: "Nablus", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Phô mai trắng kéo sợi dưới lớp bột sợi nướng giòn vàng, rưới siro và rắc hồ trăn, ăn nóng."},
{ten: "Sabich", goc: "סביח", am_thuc: "trungdong", vung: "Israel", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Bánh pita nhồi cà tím chiên, trứng luộc, salad, sốt tahini và sốt xoài muối amba."},
{ten: "Iskender kebab", goc: "", am_thuc: "trungdong", vung: "Bursa", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Thịt döner thái mỏng trên bánh pide, rưới sốt cà chua, bơ nâu nóng và sữa chua mát lạnh."},
{ten: "Adana kebab", goc: "", am_thuc: "trungdong", vung: "Adana", bua: ["toi"], loai: "nuong", mo_ta: "Thịt cừu băm trộn ớt đỏ nặn quanh xiên sắt to nướng than, cay thơm, ăn với hành sumac."},
{ten: "Lahmacun", goc: "", am_thuc: "trungdong", vung: "Thổ Nhĩ Kỳ", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh mì mỏng giòn phết thịt băm cà chua ớt, rắc rau mùi tây, vắt chanh rồi cuộn lại mà ăn."},
{ten: "Pide", goc: "", am_thuc: "trungdong", vung: "Biển Đen", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh mì hình thuyền nướng lò củi, nhân phô mai, thịt băm hoặc trứng, xé từng miếng nóng hổi."},
{ten: "Menemen", goc: "", am_thuc: "trungdong", vung: "Thổ Nhĩ Kỳ", bua: ["sang"], loai: "kho", mo_ta: "Trứng đảo mềm cùng cà chua, ớt xanh và dầu ô liu trong chảo nhỏ, chấm bánh mì cho bữa sáng."},
{ten: "Bánh mì Simit", goc: "Simit", am_thuc: "trungdong", vung: "Istanbul", bua: ["sang"], loai: "anvat", mo_ta: "Bánh mì vòng nhúng mật nho phủ kín mè rang, giòn vỏ dai ruột, mua ở xe đẩy góc phố Istanbul."},
{ten: "İmam bayıldı", goc: "", am_thuc: "trungdong", vung: "Thổ Nhĩ Kỳ", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cà tím nhồi hành tây, tỏi, cà chua om dầu ô liu, tên món kể rằng vị tu sĩ ngất vì quá ngon."},
{ten: "Mantı", goc: "", am_thuc: "trungdong", vung: "Kayseri", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh bao tí hon nhân thịt cừu phủ sữa chua tỏi, rưới bơ ớt đỏ, rắc bạc hà khô."},
{ten: "Kumpir", goc: "", am_thuc: "trungdong", vung: "Istanbul", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Củ khoai tây nướng to trộn bơ và phô mai, chất đầy bắp, ô liu, xúc xích, dưa chua tùy chọn."},
{ten: "Bánh mì kẹp cá Balık ekmek", goc: "Balık ekmek", am_thuc: "trungdong", vung: "Istanbul", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Phi lê cá thu nướng kẹp bánh mì với hành tây và rau, mua trên thuyền bên cầu Galata."},
{ten: "Baklava", goc: "", am_thuc: "trungdong", vung: "Gaziantep", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Hàng chục lớp bột mỏng như giấy xếp xen hồ trăn, nướng giòn rồi ngâm siro, ngọt lịm thơm bơ."},
{ten: "Kẹo Lokum", goc: "Lokum", am_thuc: "trungdong", vung: "Istanbul", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Kẹo dẻo vuông vị hoa hồng, chanh hay hồ trăn phủ đường bột, mềm dai ngọt dịu, mời cùng cà phê."},
{ten: "Cà phê Thổ Nhĩ Kỳ", goc: "Türk kahvesi", am_thuc: "trungdong", vung: "Istanbul", bua: ["sang", "trua", "toi"], loai: "douong", mo_ta: "Cà phê xay mịn đun trong ấm đồng nhỏ, đặc sánh có bọt, uống xong úp cốc để đoán vận mệnh."},
{ten: "Ayran", goc: "", am_thuc: "trungdong", vung: "Thổ Nhĩ Kỳ", bua: ["trua", "toi"], loai: "douong", mo_ta: "Sữa chua pha nước và chút muối đánh nổi bọt, mằn mặn mát lạnh, uống cùng kebab là chuẩn."},
{ten: "Chelo kebab", goc: "چلوکباب · Chelow kabab", am_thuc: "trungdong", vung: "Tehran", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Cơm gạo dài nghệ tây với xiên thịt băm nướng, cà chua nướng và miếng bơ tan trên cơm."},
{ten: "Ghormeh sabzi", goc: "قورمه سبزی", am_thuc: "trungdong", vung: "Iran", bua: ["trua", "toi"], loai: "kho", mo_ta: "Món hầm rau thơm xào kỹ với đậu đỏ, thịt cừu và chanh khô, chua nhẹ thơm nồng, ăn với cơm."},
{ten: "Fesenjan", goc: "فسنجان", am_thuc: "trungdong", vung: "Iran", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà hầm trong sốt quả óc chó xay và siro lựu, nâu sẫm sánh mịn, chua ngọt bùi béo."},
{ten: "Tahdig", goc: "ته دیگ", am_thuc: "trungdong", vung: "Iran", bua: ["trua", "toi"], loai: "kho", mo_ta: "Lớp cơm cháy vàng giòn ở đáy nồi, úp ra như chiếc bánh, phần cả nhà tranh nhau đầu tiên."},
{ten: "Ash reshteh", goc: "آش رشته", am_thuc: "trungdong", vung: "Iran", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp đặc với mì sợi, đậu, rau thơm, phủ sữa chua khô kashk, hành phi và bạc hà phi."},
{ten: "Kabsa", goc: "كبسة", am_thuc: "trungdong", vung: "Ả Rập Xê Út", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cơm gạo dài nấu cùng gà hoặc cừu với gia vị ấm, nho khô và hạnh nhân, đĩa to cho cả nhà."},
{ten: "Mandi", goc: "مندي", am_thuc: "trungdong", vung: "Yemen", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Thịt cừu hoặc gà nướng chậm trong lò đất dưới lòng đất, mềm rời xương, đặt trên cơm thơm khói."},
{ten: "Luqaimat", goc: "لقيمات", am_thuc: "trungdong", vung: "UAE", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Viên bột chiên tròn vàng giòn rưới siro chà là, rắc mè, món ngọt tháng Ramadan."},
{ten: "Cà phê Ả Rập", goc: "قهوة عربية · Qahwa", am_thuc: "trungdong", vung: "Ả Rập Xê Út", bua: ["sang", "trua", "toi"], loai: "douong", mo_ta: "Cà phê rang nhạt nấu với bạch đậu khấu, rót tách nhỏ không quai, mời khách kèm chà là."},
{ten: "Couscous", goc: "كسكس · Kuskus", am_thuc: "trungdong", vung: "Maroc", bua: ["trua", "toi"], loai: "kho", mo_ta: "Hạt bột semolina hấp tơi xốp phủ rau củ hầm và thịt cừu, món của bữa trưa thứ Sáu ở Maroc."},
{ten: "Tagine gà chanh muối", goc: "طاجين · Tajine", am_thuc: "trungdong", vung: "Maroc", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà hầm trong nồi đất nắp nhọn với chanh muối và ô liu, thơm nghệ gừng, chấm bánh mì."},
{ten: "Pastilla", goc: "بسطيلة · Bastila", am_thuc: "trungdong", vung: "Fes", bua: ["toi"], loai: "kho", mo_ta: "Bánh nướng nhiều lớp bột mỏng nhân gà, hạnh nhân, gia vị, phủ đường bột và quế, mặn ngọt lạ lùng."},
{ten: "Súp Harira", goc: "حريرة · Harira", am_thuc: "trungdong", vung: "Maroc", bua: ["toi"], loai: "nuoc", mo_ta: "Súp cà chua đậu lăng, đậu gà và thịt, thơm rau mùi, người Maroc dùng để xả chay tháng Ramadan."},
{ten: "Trà bạc hà Maroc", goc: "أتاي · Atay", am_thuc: "trungdong", vung: "Maroc", bua: ["sang", "trua", "toi"], loai: "douong", mo_ta: "Trà xanh với bạc hà tươi và đường, rót từ trên cao cho nổi bọt, mời ba lần là phép lịch sự."},
{ten: "Xúc xích Merguez", goc: "مرقاز · Merguez", am_thuc: "trungdong", vung: "Tunisia", bua: ["toi"], loai: "nuong", mo_ta: "Xúc xích cừu nhỏ đỏ cay vị harissa và thì là, nướng than chảy mỡ, kẹp bánh mì baguette."},
{ten: "Brik", goc: "بريك", am_thuc: "trungdong", vung: "Tunisia", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh bột mỏng gói trứng, cá ngừ, rau mùi tây chiên giòn, cắn khéo để lòng đỏ không chảy."},
{ten: "Shakshuka", goc: "شكشوكة", am_thuc: "trungdong", vung: "Tunisia", bua: ["sang", "trua"], loai: "kho", mo_ta: "Trứng chần trong sốt cà chua ớt chuông cay thơm thì là, bưng nguyên chảo, chấm bánh mì."},
{ten: "Bánh Msemen", goc: "مسمن · Msemen", am_thuc: "trungdong", vung: "Maroc", bua: ["sang"], loai: "anvat", mo_ta: "Bánh mì dẹt vuông gấp nhiều lớp áp chảo giòn, phết mật ong và bơ, ăn cùng trà bạc hà."},
{ten: "Ful medames", goc: "فول مدمس", am_thuc: "trungdong", vung: "Ai Cập", bua: ["sang"], loai: "kho", mo_ta: "Đậu tằm hầm nhừ trộn dầu ô liu, thì là, chanh, ăn với bánh mì baladi, bữa sáng của Cairo."},
{ten: "Koshari", goc: "كشري", am_thuc: "trungdong", vung: "Ai Cập", bua: ["trua", "toi", "khuya"], loai: "kho", mo_ta: "Cơm, đậu lăng, nui, đậu gà xếp lớp, rưới sốt cà chua giấm cay, phủ hành phi giòn."},
{ten: "Molokhia", goc: "ملوخية", am_thuc: "trungdong", vung: "Ai Cập", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Lá đay băm nấu nước dùng gà với tỏi phi và rau mùi, sánh nhớt mát, ăn với cơm hoặc bánh mì."},
{ten: "Umm Ali", goc: "أم علي", am_thuc: "trungdong", vung: "Ai Cập", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh bột ngàn lớp nướng trong sữa ngọt với hạt và nho khô, như bánh mì pudding kiểu Ai Cập."},
{ten: "Hawawshi", goc: "حواوشي", am_thuc: "trungdong", vung: "Ai Cập", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh mì baladi nhồi thịt băm trộn hành ớt gia vị rồi nướng giòn, mỡ thấm vào vỏ bánh."},

// Châu Âu
{ten: "Pizza Margherita", goc: "", am_thuc: "au", vung: "Napoli", bua: ["trua", "toi", "khuya"], loai: "kho", mo_ta: "Đế bánh mỏng phồng viền cháy lốm đốm, sốt cà chua, phô mai mozzarella và lá húng quế, ba màu cờ Ý."},
{ten: "Calzone", goc: "", am_thuc: "au", vung: "Napoli", bua: ["trua", "toi"], loai: "kho", mo_ta: "Pizza gập đôi hình bán nguyệt, bên trong là ricotta, mozzarella và xúc xích nóng chảy, nướng phồng vàng."},
{ten: "Mì Ý Carbonara", goc: "Spaghetti alla carbonara", am_thuc: "au", vung: "Roma", bua: ["trua", "toi"], loai: "kho", mo_ta: "Mì trộn lòng đỏ trứng, phô mai pecorino, má heo muối giòn và nhiều tiêu đen, béo mượt không cần kem."},
{ten: "Mì Ý sốt bò bằm", goc: "Tagliatelle al ragù alla bolognese", am_thuc: "au", vung: "Bologna", bua: ["trua", "toi"], loai: "kho", mo_ta: "Sợi mì dẹt quyện sốt thịt bò heo hầm chậm với cà chua và rau thơm, kiểu chính gốc thành Bologna."},
{ten: "Lasagna", goc: "Lasagne alla bolognese", am_thuc: "au", vung: "Bologna", bua: ["trua", "toi"], loai: "kho", mo_ta: "Những lớp mì lá xen sốt thịt bằm, sốt kem béchamel và phô mai nướng vàng, cắt miếng vuông nóng hổi."},
{ten: "Risotto nghệ tây", goc: "Risotto alla milanese", am_thuc: "au", vung: "Milano", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gạo arborio khuấy từng muôi nước dùng với nghệ tây, bơ và phô mai, vàng óng sánh như kem."},
{ten: "Cacio e pepe", goc: "", am_thuc: "au", vung: "Roma", bua: ["trua", "toi"], loai: "kho", mo_ta: "Mì trộn phô mai pecorino và tiêu đen xay, chỉ ba nguyên liệu mà béo thơm đến bất ngờ."},
{ten: "Mì Ý Amatriciana", goc: "Bucatini all'amatriciana", am_thuc: "au", vung: "Lazio", bua: ["trua", "toi"], loai: "kho", mo_ta: "Sợi mì ống dài trong sốt cà chua với má heo muối chiên và phô mai pecorino, mặn mà thơm mỡ."},
{ten: "Mì Ý sốt pesto", goc: "Trofie al pesto", am_thuc: "au", vung: "Genova", bua: ["trua", "toi"], loai: "kho", mo_ta: "Sợi mì xoắn nhỏ trộn sốt húng quế giã với hạt thông, tỏi, phô mai và dầu ô liu, xanh mướt thơm lừng."},
{ten: "Mì Ý tỏi ớt", goc: "Spaghetti aglio, olio e peperoncino", am_thuc: "au", vung: "Napoli", bua: ["trua", "toi", "khuya"], loai: "kho", mo_ta: "Mì trộn tỏi phi vàng, ớt khô và dầu ô liu, món nửa đêm đơn giản của người Ý khi tủ lạnh trống."},
{ten: "Mì Ý nghêu", goc: "Spaghetti alle vongole", am_thuc: "au", vung: "Napoli", bua: ["trua", "toi"], loai: "kho", mo_ta: "Nghêu tươi mở miệng trong dầu ô liu, tỏi, rượu vang trắng, quyện vào sợi mì, rắc mùi tây."},
{ten: "Mì Ý cay Arrabbiata", goc: "Penne all'arrabbiata", am_thuc: "au", vung: "Roma", bua: ["trua", "toi"], loai: "kho", mo_ta: "Mì ống penne trong sốt cà chua tỏi ớt cay nồng, tên món nghĩa là cơn giận dữ."},
{ten: "Gnocchi khoai tây", goc: "Gnocchi di patate", am_thuc: "au", vung: "Ý", bua: ["trua", "toi"], loai: "kho", mo_ta: "Những viên bột khoai tây mềm như gối nhỏ, luộc chín rồi trộn bơ xô thơm hoặc sốt cà chua."},
{ten: "Ravioli", goc: "", am_thuc: "au", vung: "Emilia-Romagna", bua: ["trua", "toi"], loai: "kho", mo_ta: "Mì vuông nhân phô mai ricotta và rau bina, rưới bơ lá xô thơm và phô mai bào."},
{ten: "Osso buco", goc: "Ossobuco alla milanese", am_thuc: "au", vung: "Milano", bua: ["toi"], loai: "kho", mo_ta: "Bắp chân bê hầm rau củ đến mềm, tủy xương béo ngậy, rắc vỏ chanh tỏi mùi tây, ăn với risotto."},
{ten: "Vitello tonnato", goc: "", am_thuc: "au", vung: "Piemonte", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt bê luộc nguội thái mỏng phủ sốt cá ngừ, nụ bạch hoa và mayonnaise, món mát ngày hè."},
{ten: "Saltimbocca", goc: "Saltimbocca alla romana", am_thuc: "au", vung: "Roma", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt bê mỏng đặt lá xô thơm và lát giăm bông, áp chảo bơ và vang trắng, ngon nhảy vào miệng."},
{ten: "Bít tết Florence", goc: "Bistecca alla fiorentina", am_thuc: "au", vung: "Firenze", bua: ["toi"], loai: "nuong", mo_ta: "Miếng sườn bò chữ T dày ba ngón tay nướng than, chín tái, chỉ rắc muối và dầu ô liu."},
{ten: "Arancini", goc: "", am_thuc: "au", vung: "Sicilia", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Cơm nắm viên nhân thịt sốt cà và mozzarella, lăn vụn bánh mì chiên vàng như quả cam nhỏ."},
{ten: "Salad Caprese", goc: "Insalata caprese", am_thuc: "au", vung: "Capri", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Lát cà chua chín xen mozzarella tươi và lá húng quế, rưới dầu ô liu, đơn giản mà tươi rói."},
{ten: "Bruschetta", goc: "", am_thuc: "au", vung: "Ý", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh mì nướng chà tỏi phủ cà chua thái hạt lựu, húng quế và dầu ô liu, món khai vị giòn thơm."},
{ten: "Focaccia", goc: "Focaccia genovese", am_thuc: "au", vung: "Genova", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Bánh mì dẹt mềm xốp nhiều lỗ, rưới đẫm dầu ô liu, rắc muối hột và hương thảo."},
{ten: "Súp Minestrone", goc: "Minestrone", am_thuc: "au", vung: "Ý", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp rau củ đặc với đậu, cà chua, mì ống nhỏ, rắc phô mai, bát súp mùa nào thức nấy của nhà Ý."},
{ten: "Ribollita", goc: "", am_thuc: "au", vung: "Toscana", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp bánh mì nấu lại với đậu trắng, cải xoăn đen và rau củ, đặc sánh, ngày hôm sau ăn càng ngon."},
{ten: "Carpaccio bò", goc: "Carpaccio", am_thuc: "au", vung: "Venezia", bua: ["toi"], loai: "anvat", mo_ta: "Thịt bò sống thái mỏng như giấy, rưới dầu ô liu, chanh, rắc phô mai bào và rau rocket."},
{ten: "Porchetta", goc: "", am_thuc: "au", vung: "Lazio", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Thịt heo cuộn tròn nhồi thì là, tỏi, hương thảo quay đến da giòn, thái lát kẹp bánh mì."},
{ten: "Parmigiana cà tím", goc: "Parmigiana di melanzane", am_thuc: "au", vung: "Campania", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cà tím chiên xếp lớp với sốt cà chua, mozzarella và parmigiano, nướng vàng sủi bọt."},
{ten: "Piadina", goc: "", am_thuc: "au", vung: "Romagna", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh mì dẹt mỏng nướng chảo kẹp giăm bông, phô mai mềm và rau rocket, gập đôi ăn ngay."},
{ten: "Tiramisu", goc: "Tiramisù", am_thuc: "au", vung: "Veneto", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh quy ngâm cà phê xếp lớp với kem mascarpone, rắc bột cacao, tên có nghĩa là hãy nâng tôi lên."},
{ten: "Panna cotta", goc: "", am_thuc: "au", vung: "Piemonte", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Kem sữa đông mềm run rẩy thơm vani, rưới sốt dâu rừng hoặc caramel, mát và nhẹ nhàng."},
{ten: "Cannoli", goc: "", am_thuc: "au", vung: "Sicilia", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Vỏ bánh chiên giòn hình ống nhồi kem ricotta ngọt, đính sô cô la chip và vỏ cam, đặc sản Sicilia."},
{ten: "Kem Gelato", goc: "Gelato", am_thuc: "au", vung: "Ý", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Kem Ý đặc mịn ít bọt khí hơn kem thường, vị hồ trăn, hạt phỉ, chanh, ăn bằng chiếc thìa xẻng nhỏ."},
{ten: "Affogato", goc: "Affogato al caffè", am_thuc: "au", vung: "Ý", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Một viên kem vani dìm trong tách espresso nóng, tan chảy thành dòng ngọt đắng quyện nhau."},
{ten: "Panettone", goc: "", am_thuc: "au", vung: "Milano", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh mì ngọt cao như chiếc mũ, mềm xốp với nho khô và vỏ cam, món Giáng sinh của người Ý."},
{ten: "Espresso", goc: "", am_thuc: "au", vung: "Ý", bua: ["sang", "trua", "toi"], loai: "douong", mo_ta: "Tách cà phê nhỏ đặc sánh với lớp bọt crema nâu vàng, uống đứng ngay quầy trong ba ngụm."},
{ten: "Cappuccino", goc: "", am_thuc: "au", vung: "Ý", bua: ["sang"], loai: "douong", mo_ta: "Espresso với sữa nóng và lớp bọt sữa dày mịn, người Ý chỉ uống vào buổi sáng thôi."},
{ten: "Bánh sừng bò", goc: "Croissant", am_thuc: "au", vung: "Paris", bua: ["sang"], loai: "anvat", mo_ta: "Bánh bơ nhiều lớp mỏng giòn tan ở ngoài, ruột xốp như tổ ong, chấm cà phê sữa buổi sáng."},
{ten: "Pain au chocolat", goc: "", am_thuc: "au", vung: "Paris", bua: ["sang"], loai: "anvat", mo_ta: "Bánh bơ cán lớp như croissant với hai thanh sô cô la đen bên trong, giòn vụn ngọt đắng."},
{ten: "Crêpe", goc: "", am_thuc: "au", vung: "Bretagne", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh kếp mỏng như lụa phết bơ đường, mứt hay sô cô la hạt phỉ, gấp tư cầm tay đi dạo."},
{ten: "Galette Bretagne", goc: "Galette bretonne", am_thuc: "au", vung: "Bretagne", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh kếp bột kiều mạch nâu giòn viền, gấp vuông quanh trứng, giăm bông và phô mai chảy."},
{ten: "Quiche Lorraine", goc: "", am_thuc: "au", vung: "Lorraine", bua: ["trua", "toi"], loai: "kho", mo_ta: "Đế bánh giòn đựng hỗn hợp trứng, kem và thịt xông khói nướng vàng, cắt miếng ăn nóng hay nguội."},
{ten: "Croque monsieur", goc: "", am_thuc: "au", vung: "Paris", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh mì sandwich kẹp giăm bông, phủ sốt béchamel và phô mai gruyère nướng vàng sủi bọt."},
{ten: "Bò hầm vang đỏ", goc: "Bœuf bourguignon", am_thuc: "au", vung: "Bourgogne", bua: ["toi"], loai: "kho", mo_ta: "Thịt bò hầm chậm với vang đỏ Bourgogne, nấm, hành nhỏ và thịt xông khói, sốt sánh đậm đà."},
{ten: "Gà hầm vang", goc: "Coq au vin", am_thuc: "au", vung: "Bourgogne", bua: ["toi"], loai: "kho", mo_ta: "Gà hầm rượu vang với nấm, hành và thịt xông khói, thịt mềm thấm màu đỏ sẫm, chấm bánh mì."},
{ten: "Ratatouille", goc: "", am_thuc: "au", vung: "Provence", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cà tím, bí ngòi, ớt chuông, cà chua hầm với dầu ô liu và thảo mộc Provence, rực rỡ sắc hè."},
{ten: "Súp cá Bouillabaisse", goc: "Bouillabaisse", am_thuc: "au", vung: "Marseille", bua: ["toi"], loai: "nuoc", mo_ta: "Súp cá và hải sản nấu nghệ tây, thì là, vỏ cam, ăn kèm bánh mì nướng phết sốt rouille."},
{ten: "Súp hành Pháp", goc: "Soupe à l'oignon gratinée", am_thuc: "au", vung: "Paris", bua: ["toi", "khuya"], loai: "nuoc", mo_ta: "Hành tây xào caramel nấu súp, phủ bánh mì và phô mai nướng chảy kéo sợi, ấm lòng đêm lạnh."},
{ten: "Bít tết khoai tây chiên", goc: "Steak frites", am_thuc: "au", vung: "Paris", bua: ["trua", "toi"], loai: "kho", mo_ta: "Miếng thăn bò áp chảo vừa tới, sốt tiêu hoặc bơ thảo mộc, ăn kèm đĩa khoai tây chiên giòn."},
{ten: "Đùi vịt confit", goc: "Confit de canard", am_thuc: "au", vung: "Tây Nam Pháp", bua: ["toi"], loai: "kho", mo_ta: "Đùi vịt ninh chậm trong chính mỡ vịt rồi áp chảo da giòn, thịt mềm rời xương, ăn với khoai tây."},
{ten: "Ốc sên bơ tỏi", goc: "Escargots de Bourgogne", am_thuc: "au", vung: "Bourgogne", bua: ["toi"], loai: "anvat", mo_ta: "Ốc sên nướng trong vỏ với bơ tỏi mùi tây sôi xèo, chấm bánh mì vào phần bơ là tuyệt nhất."},
{ten: "Cassoulet", goc: "", am_thuc: "au", vung: "Languedoc", bua: ["toi"], loai: "kho", mo_ta: "Đậu trắng hầm nồi đất với xúc xích, thịt heo và đùi vịt confit, lớp vỏ trên nướng giòn."},
{ten: "Blanquette de veau", goc: "", am_thuc: "au", vung: "Pháp", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt bê hầm trong sốt kem trắng với nấm và hành nhỏ, nhẹ nhàng thơm béo, ăn với cơm trắng."},
{ten: "Salad Niçoise", goc: "Salade niçoise", am_thuc: "au", vung: "Nice", bua: ["trua"], loai: "anvat", mo_ta: "Cá ngừ, trứng luộc, ô liu đen, cà chua, đậu que và cá cơm, salad đầy đặn của miền biển Nice."},
{ten: "Vẹm hấp vang trắng", goc: "Moules marinières", am_thuc: "au", vung: "Bretagne", bua: ["toi"], loai: "kho", mo_ta: "Một nồi vẹm hấp vang trắng, hẹ tây và mùi tây, chấm bánh mì vào nước hấp, ăn kèm khoai chiên."},
{ten: "Gratin khoai tây", goc: "Gratin dauphinois", am_thuc: "au", vung: "Grenoble", bua: ["trua", "toi"], loai: "kho", mo_ta: "Khoai tây thái mỏng nướng trong kem sữa tỏi đến mềm tan, mặt trên vàng ruộm thơm lừng."},
{ten: "Tartiflette", goc: "", am_thuc: "au", vung: "Savoie", bua: ["toi"], loai: "kho", mo_ta: "Khoai tây, thịt xông khói, hành nướng phủ nguyên bánh phô mai reblochon chảy, món của dân trượt tuyết."},
{ten: "Pot-au-feu", goc: "", am_thuc: "au", vung: "Pháp", bua: ["toi"], loai: "nuoc", mo_ta: "Thịt bò, xương tủy và rau củ hầm chậm trong nồi lớn, nước dùng trong thơm, ăn với mù tạt và muối hột."},
{ten: "Soufflé phô mai", goc: "Soufflé au fromage", am_thuc: "au", vung: "Pháp", bua: ["toi"], loai: "kho", mo_ta: "Trứng đánh bông với phô mai nướng phồng cao khỏi khuôn, phải ăn ngay trước khi xẹp xuống."},
{ten: "Crème brûlée", goc: "", am_thuc: "au", vung: "Pháp", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Kem trứng vani mịn dưới lớp đường khò cháy giòn như kính, gõ thìa nghe tách một tiếng."},
{ten: "Macaron", goc: "", am_thuc: "au", vung: "Paris", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Hai vỏ bánh hạnh nhân giòn nhẹ dẻo trong kẹp nhân kem đủ màu, nhỏ xinh như những viên kẹo."},
{ten: "Bánh Éclair", goc: "Éclair", am_thuc: "au", vung: "Paris", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Vỏ bánh su dài nhồi kem trứng vani hay cà phê, phủ lớp sô cô la bóng, ăn nhanh như chớp."},
{ten: "Tarte Tatin", goc: "", am_thuc: "au", vung: "Loire", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Táo caramel nướng dưới lớp bột rồi lật úp ra, ngọt sánh óng ánh, ăn ấm với kem tươi."},
{ten: "Mousse sô cô la", goc: "Mousse au chocolat", am_thuc: "au", vung: "Pháp", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Sô cô la đen đánh với lòng trắng trứng bông nhẹ như mây, đắng ngọt tan dần trên lưỡi."},
{ten: "Bánh Madeleine", goc: "Madeleine", am_thuc: "au", vung: "Lorraine", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh bông lan nhỏ hình vỏ sò bụng phồng, thơm bơ và vỏ chanh, nhúng vào trà mà nhớ chuyện cũ."},
{ten: "Canelé", goc: "", am_thuc: "au", vung: "Bordeaux", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh nhỏ vỏ caramel nâu sẫm giòn, ruột mềm ẩm thơm vani và rượu rum, đặc sản Bordeaux."},
{ten: "Sô cô la nóng", goc: "Chocolat chaud", am_thuc: "au", vung: "Paris", bua: ["sang", "trua", "toi"], loai: "douong", mo_ta: "Sô cô la đen tan trong sữa nóng đặc sánh như kem, rót vào tách nhỏ, ngọt đắng ấm lòng ngày đông."},
{ten: "Paella Valencia", goc: "Paella valenciana", am_thuc: "au", vung: "Valencia", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cơm nghệ tây nấu chảo rộng với gà, thỏ và đậu, lớp cơm cháy socarrat dưới đáy là phần quý nhất."},
{ten: "Tortilla Tây Ban Nha", goc: "Tortilla de patatas", am_thuc: "au", vung: "Tây Ban Nha", bua: ["sang", "trua", "toi"], loai: "kho", mo_ta: "Trứng chiên dày với khoai tây và hành tây, lòng còn mềm, cắt miếng như bánh ăn nóng hay nguội."},
{ten: "Gazpacho", goc: "", am_thuc: "au", vung: "Andalucía", bua: ["trua"], loai: "nuoc", mo_ta: "Súp lạnh xay cà chua, dưa leo, ớt chuông, tỏi và dầu ô liu, mát rượi giữa trưa hè Andalucía."},
{ten: "Jamón ibérico", goc: "", am_thuc: "au", vung: "Tây Ban Nha", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Đùi heo đen nuôi hạt sồi muối hong nhiều năm, lạng mỏng gần trong suốt, mỡ tan trên đầu lưỡi."},
{ten: "Patatas bravas", goc: "", am_thuc: "au", vung: "Madrid", bua: ["toi", "khuya"], loai: "anvat", mo_ta: "Khoai tây cắt khối chiên giòn rưới sốt cay đỏ và sốt tỏi trắng, món tapas quán nào cũng có."},
{ten: "Churros sô cô la", goc: "Churros con chocolate", am_thuc: "au", vung: "Madrid", bua: ["sang", "khuya"], loai: "trangmieng", mo_ta: "Que bột chiên giòn xoắn rãnh rắc đường, nhúng vào tách sô cô la nóng đặc sánh."},
{ten: "Tôm tỏi ớt", goc: "Gambas al ajillo", am_thuc: "au", vung: "Andalucía", bua: ["toi"], loai: "anvat", mo_ta: "Tôm nấu sôi trong nồi đất nhỏ với dầu ô liu, tỏi lát và ớt khô, chấm bánh mì vào dầu thơm."},
{ten: "Bạch tuộc Galicia", goc: "Pulpo a la gallega", am_thuc: "au", vung: "Galicia", bua: ["toi"], loai: "anvat", mo_ta: "Bạch tuộc luộc mềm thái khoanh trên khoai tây, rắc ớt bột paprika, muối hột và dầu ô liu."},
{ten: "Croquetas", goc: "Croquetas de jamón", am_thuc: "au", vung: "Tây Ban Nha", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Viên sốt béchamel với giăm bông lăn vụn bánh mì chiên giòn, bên trong mềm tan như kem."},
{ten: "Pan con tomate", goc: "Pa amb tomàquet", am_thuc: "au", vung: "Catalunya", bua: ["sang"], loai: "anvat", mo_ta: "Bánh mì nướng chà cà chua chín và tỏi, rưới dầu ô liu, rắc muối, đơn giản mà ngon lạ."},
{ten: "Fabada", goc: "Fabada asturiana", am_thuc: "au", vung: "Asturias", bua: ["trua"], loai: "nuoc", mo_ta: "Đậu trắng to hầm với xúc xích chorizo, dồi huyết morcilla và thịt heo, đậm đà cho ngày lạnh."},
{ten: "Cocido madrileño", goc: "", am_thuc: "au", vung: "Madrid", bua: ["trua"], loai: "nuoc", mo_ta: "Đậu gà hầm với thịt, xúc xích và rau, ăn ba lượt: súp mì trước, rồi đậu, rồi đến thịt."},
{ten: "Bánh mì mực chiên", goc: "Bocadillo de calamares", am_thuc: "au", vung: "Madrid", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Ổ bánh mì giòn kẹp đầy khoanh mực chiên vàng, món nhanh gọn quanh quảng trường Plaza Mayor."},
{ten: "Pintxos", goc: "", am_thuc: "au", vung: "San Sebastián", bua: ["toi"], loai: "anvat", mo_ta: "Những miếng bánh mì nhỏ xiên tăm với cá, thịt, ớt, trứng bày đầy quầy, chọn từng chiếc mà ăn."},
{ten: "Crema catalana", goc: "", am_thuc: "au", vung: "Catalunya", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Kem trứng thơm vỏ chanh và quế, phủ đường khò cháy giòn, người anh em của crème brûlée."},
{ten: "Bánh tart trứng Bồ Đào Nha", goc: "Pastel de nata", am_thuc: "au", vung: "Lisboa", bua: ["sang", "trua", "toi"], loai: "trangmieng", mo_ta: "Vỏ bánh ngàn lớp giòn rụm ôm nhân trứng sữa cháy lốm đốm, rắc quế, ăn khi còn ấm ở Belém."},
{ten: "Bacalhau à Brás", goc: "", am_thuc: "au", vung: "Lisboa", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cá tuyết muối xé sợi xào với khoai tây sợi chiên, trứng và hành, rắc ô liu và mùi tây."},
{ten: "Francesinha", goc: "", am_thuc: "au", vung: "Porto", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh sandwich nhiều tầng thịt và xúc xích, phủ phô mai chảy và sốt cà chua đậm, ăn kèm khoai chiên."},
{ten: "Caldo verde", goc: "", am_thuc: "au", vung: "Minho", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp khoai tây nghiền với cải xoăn thái sợi mảnh và lát xúc xích chouriço, ấm áp giản dị."},
{ten: "Bifana", goc: "", am_thuc: "au", vung: "Lisboa", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Thịt heo thái mỏng ướp tỏi và vang trắng, kẹp bánh mì giòn, quệt thêm mù tạt vàng."},
{ten: "Gà Piri-piri", goc: "Frango piri-piri", am_thuc: "au", vung: "Algarve", bua: ["toi"], loai: "nuong", mo_ta: "Gà xẻ đôi nướng than phết sốt ớt piri-piri cay chua, da cháy cạnh, ăn với khoai chiên."},
{ten: "Cá mòi nướng", goc: "Sardinhas assadas", am_thuc: "au", vung: "Lisboa", bua: ["toi"], loai: "nuong", mo_ta: "Cá mòi tươi rắc muối nướng than đặt trên lát bánh mì, mùi khói lan khắp phố mỗi tháng Sáu."},
{ten: "Moussaka", goc: "Μουσακάς · Mousakás", am_thuc: "au", vung: "Hy Lạp", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cà tím chiên xếp lớp với thịt cừu băm sốt cà chua quế, phủ sốt béchamel dày, nướng vàng."},
{ten: "Souvlaki", goc: "Σουβλάκι · Souvláki", am_thuc: "au", vung: "Hy Lạp", bua: ["trua", "toi", "khuya"], loai: "nuong", mo_ta: "Xiên thịt heo hoặc gà ướp chanh, oregano nướng than, ăn với bánh pita, cà chua và sốt tzatziki."},
{ten: "Gyros", goc: "Γύρος · Gýros", am_thuc: "au", vung: "Athens", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Thịt quay trên trục đứng lạng mỏng cuộn bánh pita cùng khoai chiên, hành, cà chua và tzatziki."},
{ten: "Salad Hy Lạp", goc: "Χωριάτικη · Choriátiki", am_thuc: "au", vung: "Hy Lạp", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Cà chua, dưa leo, hành tím, ô liu và nguyên miếng phô mai feta, rưới dầu ô liu rắc oregano."},
{ten: "Spanakopita", goc: "Σπανακόπιτα · Spanakópita", am_thuc: "au", vung: "Hy Lạp", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Bánh bột phyllo nhiều lớp mỏng giòn nhân rau bina và phô mai feta, nướng vàng thơm bơ."},
{ten: "Tzatziki", goc: "Τζατζίκι · Tzatzíki", am_thuc: "au", vung: "Hy Lạp", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Sữa chua đặc trộn dưa leo bào, tỏi, thì là và dầu ô liu, mát lạnh, chấm bánh mì hay thịt nướng."},
{ten: "Dolmades", goc: "Ντολμάδες · Ntolmádes", am_thuc: "au", vung: "Hy Lạp", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Lá nho cuộn cơm trộn thảo mộc và chanh, hấp mềm chua nhẹ, món khai vị nguội thanh mát."},
{ten: "Loukoumades", goc: "Λουκουμάδες · Loukoumádes", am_thuc: "au", vung: "Hy Lạp", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Viên bột chiên phồng vàng rưới mật ong, rắc quế và óc chó, giòn ngoài mềm trong."},
{ten: "Sữa chua Hy Lạp mật ong", goc: "Γιαούρτι με μέλι · Giaoúrti me méli", am_thuc: "au", vung: "Hy Lạp", bua: ["sang", "trua"], loai: "trangmieng", mo_ta: "Sữa chua lọc đặc sánh béo rưới mật ong cỏ xạ hương và rắc óc chó, ngọt chua dịu dàng."},
{ten: "Cà phê Frappé", goc: "Φραπέ · Frapé", am_thuc: "au", vung: "Thessaloniki", bua: ["trua", "toi"], loai: "douong", mo_ta: "Cà phê hòa tan lắc với đá và đường đến nổi bọt dày, thêm sữa, uống chậm bên quán ven biển."},
{ten: "Xúc xích Bratwurst", goc: "Bratwurst", am_thuc: "au", vung: "Thüringen", bua: ["trua", "toi", "khuya"], loai: "nuong", mo_ta: "Xúc xích heo nướng than vàng giòn vỏ, kẹp bánh mì nhỏ với mù tạt, món nóng hổi ở chợ phiên."},
{ten: "Currywurst", goc: "", am_thuc: "au", vung: "Berlin", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Xúc xích chiên cắt khoanh rưới sốt cà chua cà ri, rắc bột cà ri, ăn với khoai tây chiên."},
{ten: "Giò heo Đức", goc: "Schweinshaxe", am_thuc: "au", vung: "Bayern", bua: ["toi"], loai: "nuong", mo_ta: "Giò heo quay đến lớp da nổ giòn rụm, thịt mềm, ăn với bắp cải muối và viên khoai tây."},
{ten: "Sauerbraten", goc: "", am_thuc: "au", vung: "Rheinland", bua: ["toi"], loai: "kho", mo_ta: "Thịt bò ngâm giấm và gia vị nhiều ngày rồi om, sốt chua ngọt sẫm màu, ăn với bắp cải đỏ."},
{ten: "Bánh Pretzel", goc: "Brezel", am_thuc: "au", vung: "Bayern", bua: ["sang", "trua", "toi"], loai: "anvat", mo_ta: "Bánh mì nướng thắt nút vỏ nâu bóng rắc muối hột, ruột mềm dai, chấm mù tạt ngọt."},
{ten: "Käsespätzle", goc: "", am_thuc: "au", vung: "Baden-Württemberg", bua: ["trua", "toi"], loai: "kho", mo_ta: "Mì trứng mềm vụn trộn phô mai tan chảy, phủ hành phi giòn, món no nê của vùng Swabia."},
{ten: "Rouladen", goc: "Rinderrouladen", am_thuc: "au", vung: "Đức", bua: ["toi"], loai: "kho", mo_ta: "Lát bò mỏng cuộn thịt xông khói, dưa chuột muối và mù tạt, om nước sốt nâu đậm đà."},
{ten: "Salad khoai tây Đức", goc: "Kartoffelsalat", am_thuc: "au", vung: "Đức", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Khoai tây luộc thái lát trộn giấm, hành và nước dùng, có nơi thêm thịt xông khói, ăn kèm xúc xích."},
{ten: "Leberkäse", goc: "", am_thuc: "au", vung: "Bayern", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Bánh thịt xay nướng nguyên khối vỏ nâu, thái lát dày kẹp bánh mì với mù tạt ngọt."},
{ten: "Bánh Rừng Đen", goc: "Schwarzwälder Kirschtorte", am_thuc: "au", vung: "Schwarzwald", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh sô cô la nhiều tầng xen kem tươi và anh đào ngâm, phủ sô cô la bào, đặc sản Rừng Đen."},
{ten: "Wiener Schnitzel", goc: "", am_thuc: "au", vung: "Wien", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt bê đập mỏng tẩm vụn bánh mì chiên vàng phồng, vắt chanh, ăn kèm salad khoai tây."},
{ten: "Apfelstrudel", goc: "", am_thuc: "au", vung: "Wien", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Lớp bột kéo mỏng đến đọc báo xuyên qua được cuộn táo, quế, nho khô, ăn ấm với sốt vani."},
{ten: "Sachertorte", goc: "", am_thuc: "au", vung: "Wien", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh sô cô la đặc kẹp mứt mơ, phủ lớp sô cô la bóng, ăn kèm kem tươi không đường."},
{ten: "Kaiserschmarrn", goc: "", am_thuc: "au", vung: "Áo", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh kếp dày xé vụn áp chảo bơ với nho khô, rắc đường bột, chấm mứt mận, món của hoàng đế."},
{ten: "Tafelspitz", goc: "", am_thuc: "au", vung: "Wien", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Thịt bò luộc trong nước dùng rau củ, ăn kèm sốt táo cải ngựa và khoai tây áp chảo."},
{ten: "Fondue phô mai", goc: "Fondue", am_thuc: "au", vung: "Thụy Sĩ", bua: ["toi"], loai: "nuong", mo_ta: "Nồi phô mai tan chảy sánh mịn giữa bàn, xiên bánh mì nhúng vào xoay tròn, ai làm rơi phải chịu phạt."},
{ten: "Raclette", goc: "", am_thuc: "au", vung: "Valais", bua: ["toi"], loai: "kho", mo_ta: "Khối phô mai nướng chảy được cạo xuống khoai tây luộc, ăn cùng dưa chuột bao tử và hành ngâm."},
{ten: "Rösti", goc: "", am_thuc: "au", vung: "Bern", bua: ["sang", "trua", "toi"], loai: "kho", mo_ta: "Khoai tây bào sợi áp chảo thành bánh tròn vàng giòn, ngoài giòn trong mềm, ăn kèm trứng ốp la."},
{ten: "Bircher muesli", goc: "Birchermüesli", am_thuc: "au", vung: "Zürich", bua: ["sang"], loai: "anvat", mo_ta: "Yến mạch ngâm sữa qua đêm trộn táo bào, sữa chua, hạt và trái cây, bữa sáng nhẹ mà no lâu."},
{ten: "Cá và khoai tây chiên", goc: "Fish and chips", am_thuc: "au", vung: "Anh", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cá tuyết tẩm bột chiên giòn phồng với khoai tây cắt thanh to, rưới giấm mạch nha và rắc muối."},
{ten: "Bữa sáng kiểu Anh", goc: "Full English breakfast", am_thuc: "au", vung: "Anh", bua: ["sang"], loai: "kho", mo_ta: "Trứng, thịt xông khói, xúc xích, đậu sốt cà, nấm, cà chua nướng và bánh mì, đĩa sáng to đùng."},
{ten: "Sunday roast", goc: "", am_thuc: "au", vung: "Anh", bua: ["trua"], loai: "kho", mo_ta: "Thịt bò quay, khoai tây nướng giòn, rau củ, bánh Yorkshire phồng và nước sốt gravy, bữa trưa Chủ nhật."},
{ten: "Shepherd's pie", goc: "", am_thuc: "au", vung: "Anh", bua: ["toi"], loai: "kho", mo_ta: "Thịt cừu băm sốt rau củ phủ lớp khoai tây nghiền nướng vàng giòn mặt, ấm áp kiểu nhà quê."},
{ten: "Beef Wellington", goc: "", am_thuc: "au", vung: "Anh", bua: ["toi"], loai: "kho", mo_ta: "Thăn bò bọc lớp nấm xay và giăm bông trong vỏ bánh ngàn lớp nướng vàng, cắt ra hồng đào bên trong."},
{ten: "Bangers and mash", goc: "", am_thuc: "au", vung: "Anh", bua: ["toi"], loai: "kho", mo_ta: "Xúc xích nướng nằm trên khoai tây nghiền béo mịn, chan sốt hành nâu, món quán rượu kinh điển."},
{ten: "Bánh Scone", goc: "Scone", am_thuc: "au", vung: "Devon", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh nướng xốp tách đôi phết kem đặc và mứt dâu, ăn cùng tách trà chiều đúng kiểu Anh."},
{ten: "Sticky toffee pudding", goc: "", am_thuc: "au", vung: "Anh", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh chà là xốp ẩm chìm trong sốt kẹo bơ nóng, thêm muỗng kem vani, ngọt đến nao lòng."},
{ten: "Cornish pasty", goc: "", am_thuc: "au", vung: "Cornwall", bua: ["trua"], loai: "anvat", mo_ta: "Bánh nướng hình bán nguyệt nhân thịt bò, khoai tây, củ cải và hành, bữa trưa của thợ mỏ xưa."},
{ten: "Haggis", goc: "", am_thuc: "au", vung: "Scotland", bua: ["toi"], loai: "kho", mo_ta: "Nội tạng cừu băm với yến mạch, hành và gia vị, ăn kèm củ cải và khoai tây nghiền, đậm vị tiêu."},
{ten: "Irish stew", goc: "", am_thuc: "au", vung: "Ireland", bua: ["toi"], loai: "nuoc", mo_ta: "Thịt cừu hầm chậm với khoai tây, cà rốt và hành, nước sánh ngọt tự nhiên, ấm cả ngày mưa gió."},
{ten: "Eton mess", goc: "", am_thuc: "au", vung: "Anh", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Dâu tây, bánh trứng meringue vụn và kem tươi trộn lẫn lộn xộn, ngọt mát món của mùa hè nước Anh."},
{ten: "Bánh waffle Bỉ", goc: "Gaufre de Liège", am_thuc: "au", vung: "Liège", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh waffle dày dẻo với những hạt đường nướng caramel giòn trong lòng, cầm tay ăn nóng."},
{ten: "Khoai tây chiên Bỉ", goc: "Frites", am_thuc: "au", vung: "Bruxelles", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Khoai tây cắt thanh chiên hai lần giòn rụm, đựng trong ống giấy, chấm mayonnaise kiểu Bỉ."},
{ten: "Bò hầm Flemish", goc: "Carbonade flamande", am_thuc: "au", vung: "Flanders", bua: ["toi"], loai: "kho", mo_ta: "Thịt bò hầm với hành tây caramel và bia nâu, thêm bánh mì phết mù tạt, sốt ngọt chua đậm."},
{ten: "Stroopwafel", goc: "", am_thuc: "au", vung: "Gouda", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Hai lớp bánh quế mỏng kẹp siro caramel, đặt lên miệng cốc cà phê nóng cho mềm rồi mới ăn."},
{ten: "Bitterballen", goc: "", am_thuc: "au", vung: "Hà Lan", bua: ["toi", "khuya"], loai: "anvat", mo_ta: "Viên ragu bò tẩm vụn bánh mì chiên giòn, chấm mù tạt, nóng bỏng miệng, món nhắm của quán Hà Lan."},
{ten: "Poffertjes", goc: "", am_thuc: "au", vung: "Hà Lan", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Những chiếc bánh kếp tí hon phồng xốp, phết bơ và rắc đường bột, ăn cả đĩa không hay."},
{ten: "Stamppot", goc: "", am_thuc: "au", vung: "Hà Lan", bua: ["toi"], loai: "kho", mo_ta: "Khoai tây nghiền với cải xoăn hoặc cà rốt hành, đặt lên khúc xúc xích hun khói, ấm áp mùa đông."},
{ten: "Súp củ dền Borscht", goc: "Борщ · Borshch", am_thuc: "au", vung: "Ukraine", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp củ dền đỏ thắm với bắp cải, khoai tây và thịt bò, thêm muỗng kem chua smetana và thì là."},
{ten: "Gà Kyiv", goc: "Котлета по-київськи · Kotleta po-kyivsky", am_thuc: "au", vung: "Ukraine", bua: ["trua", "toi"], loai: "kho", mo_ta: "Ức gà cuộn bơ thảo mộc tẩm vụn bánh mì chiên, cắt ra bơ nóng chảy tràn ra đĩa."},
{ten: "Pierogi", goc: "", am_thuc: "au", vung: "Ba Lan", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh bao luộc nhân khoai tây phô mai, bắp cải hoặc thịt, áp chảo bơ hành phi, chấm kem chua."},
{ten: "Súp chua Żurek", goc: "Żurek", am_thuc: "au", vung: "Ba Lan", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp chua lên men từ bột lúa mạch đen với xúc xích trắng và trứng luộc, món của lễ Phục sinh."},
{ten: "Goulash", goc: "Gulyás", am_thuc: "au", vung: "Hungary", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp bò hầm với ớt bột paprika đỏ, hành, khoai tây và cà rốt, cay ấm thơm nồng kiểu Hungary."},
{ten: "Gà sốt Paprikash", goc: "Csirkepaprikás", am_thuc: "au", vung: "Hungary", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà om sốt ớt bột paprika và kem chua hồng mịn, ăn với nhúm mì trứng nhỏ nokedli."},
{ten: "Lángos", goc: "", am_thuc: "au", vung: "Hungary", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh bột chiên phồng to như đĩa, phết tỏi, kem chua và phô mai bào, món ăn vặt bên hồ Balaton."},
{ten: "Bánh ống quế Hungary", goc: "Kürtőskalács", am_thuc: "au", vung: "Transylvania", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Dải bột quấn quanh trục nướng than, phủ đường caramel và quế, xé từng vòng xoắn nóng hổi."},
{ten: "Bò Stroganoff", goc: "Бефстроганов · Befstroganov", am_thuc: "au", vung: "Nga", bua: ["toi"], loai: "kho", mo_ta: "Thịt bò thái sợi xào với nấm và hành trong sốt kem chua, ăn kèm khoai tây nghiền hoặc mì."},
{ten: "Bánh Blini", goc: "Блины · Bliny", am_thuc: "au", vung: "Nga", bua: ["sang", "toi"], loai: "anvat", mo_ta: "Bánh kếp mỏng vàng cuộn kem chua, mứt hay trứng cá, món chính của lễ hội tiễn mùa đông Maslenitsa."},
{ten: "Pelmeni", goc: "Пельмени", am_thuc: "au", vung: "Siberia", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh bao nhỏ nhân thịt băm luộc chín, thả bơ và kem chua, món đông lạnh sẵn của mùa đông Siberia."},
{ten: "Salad Nga", goc: "Салат Оливье · Salat Olivye", am_thuc: "au", vung: "Nga", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Khoai tây, cà rốt, đậu Hà Lan, trứng, dưa chuột muối và thịt trộn mayonnaise, món đêm Giao thừa."},
{ten: "Bánh Syrniki", goc: "Сырники · Syrniki", am_thuc: "au", vung: "Nga", bua: ["sang"], loai: "anvat", mo_ta: "Bánh chiên từ phô mai tươi tvorog, vàng mềm chua nhẹ, chấm kem chua và mứt cho bữa sáng."},
{ten: "Kvass", goc: "Квас · Kvas", am_thuc: "au", vung: "Nga", bua: ["trua", "toi"], loai: "douong", mo_ta: "Nước lên men từ bánh mì lúa mạch đen, hơi chua ngọt sủi tăm, độ cồn rất thấp, uống lạnh ngày hè."},
{ten: "Sarmale", goc: "", am_thuc: "au", vung: "Romania", bua: ["trua", "toi"], loai: "kho", mo_ta: "Lá bắp cải muối cuộn thịt băm và gạo, om lâu với cà chua, ăn kèm cháo ngô và kem chua."},
{ten: "Ćevapi", goc: "", am_thuc: "au", vung: "Bosnia", bua: ["trua", "toi"], loai: "nuong", mo_ta: "Những thanh thịt băm nhỏ nướng than kẹp bánh mì dẹt somun với hành sống và kem kajmak."},
{ten: "Burek", goc: "", am_thuc: "au", vung: "Bosnia", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Bánh bột mỏng cuộn xoắn ốc nhân thịt băm hoặc phô mai, nướng giòn vàng, ăn cùng sữa chua uống."},
{ten: "Svíčková", goc: "", am_thuc: "au", vung: "Séc", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt bò ngâm rồi om, sốt kem rau củ sánh mịn, ăn với bánh bao lát knedlíky và mứt nam việt quất."},
{ten: "Smørrebrød", goc: "", am_thuc: "au", vung: "Đan Mạch", bua: ["trua"], loai: "anvat", mo_ta: "Lát bánh mì lúa mạch đen phết bơ bày cá trích, tôm, trứng hay thịt nguội, đẹp như tác phẩm nhỏ."},
{ten: "Bánh ngọt Đan Mạch", goc: "Wienerbrød", am_thuc: "au", vung: "Đan Mạch", bua: ["sang"], loai: "anvat", mo_ta: "Bánh bơ nhiều lớp xốp giòn với nhân kem trứng, mứt hoặc hạnh nhân, phủ đường trắng mỏng."},
{ten: "Thịt viên Thụy Điển", goc: "Köttbullar", am_thuc: "au", vung: "Thụy Điển", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt viên nhỏ áp chảo trong sốt kem nâu, ăn với khoai tây nghiền và mứt việt quất đỏ."},
{ten: "Bánh quế cuộn", goc: "Kanelbulle", am_thuc: "au", vung: "Thụy Điển", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh mì cuộn xoắn nhân quế và bạch đậu khấu, rắc đường hạt, đi cùng cà phê giờ nghỉ fika."},
{ten: "Cá hồi muối Gravlax", goc: "Gravlax", am_thuc: "au", vung: "Thụy Điển", bua: ["sang", "toi"], loai: "anvat", mo_ta: "Cá hồi ướp muối, đường và thì là, thái mỏng ăn với bánh mì đen và sốt mù tạt mật ong."},
{ten: "Bánh Karelia", goc: "Karjalanpiirakka", am_thuc: "au", vung: "Phần Lan", bua: ["sang"], loai: "anvat", mo_ta: "Vỏ bánh lúa mạch đen mỏng gấp viền ôm nhân cháo gạo, phết bơ trứng, bữa sáng Phần Lan."},
{ten: "Súp cá hồi Phần Lan", goc: "Lohikeitto", am_thuc: "au", vung: "Phần Lan", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp kem với cá hồi, khoai tây, tỏi tây và thì là, nhẹ nhàng béo ngậy giữa mùa đông Bắc Âu."},

// Châu Mỹ
{ten: "Burger bò phô mai", goc: "Cheeseburger", am_thuc: "my", vung: "Mỹ", bua: ["trua", "toi", "khuya"], loai: "kho", mo_ta: "Miếng bò xay áp chảo mọng nước, lát phô mai chảy, dưa chuột muối, hành, sốt, kẹp bánh mì mè."},
{ten: "Hot dog New York", goc: "", am_thuc: "my", vung: "New York", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Xúc xích bò luộc kẹp bánh mì mềm, phết mù tạt vàng, thêm hành xào hoặc dưa cải, mua ở xe đẩy góc phố."},
{ten: "Sườn heo nướng BBQ", goc: "BBQ ribs", am_thuc: "my", vung: "Memphis", bua: ["toi"], loai: "nuong", mo_ta: "Sườn heo xoa gia vị hun khói nhiều giờ đến thịt rời xương, quét sốt BBQ ngọt khói, ăn bốc tay."},
{ten: "Ức bò hun khói Texas", goc: "Texas brisket", am_thuc: "my", vung: "Texas", bua: ["toi"], loai: "nuong", mo_ta: "Ức bò xoa muối tiêu hun khói củi sồi mười mấy tiếng, vỏ đen giòn, thịt mềm mọng hồng khói."},
{ten: "Mac and cheese", goc: "", am_thuc: "my", vung: "Mỹ", bua: ["trua", "toi"], loai: "kho", mo_ta: "Nui ống trộn sốt phô mai cheddar béo ngậy, phủ vụn bánh mì nướng giòn, món an ủi tâm hồn."},
{ten: "Cánh gà Buffalo", goc: "Buffalo wings", am_thuc: "my", vung: "Buffalo", bua: ["toi", "khuya"], loai: "anvat", mo_ta: "Cánh gà chiên giòn lăn sốt ớt bơ chua cay, chấm sốt phô mai xanh, ăn cùng cần tây mát."},
{ten: "Súp nghêu kem", goc: "New England clam chowder", am_thuc: "my", vung: "Boston", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp kem sánh với nghêu, khoai tây và thịt xông khói, rắc bánh quy giòn, có nơi đựng trong ổ bánh mì."},
{ten: "Bánh mì tôm hùm", goc: "Lobster roll", am_thuc: "my", vung: "Maine", bua: ["trua"], loai: "anvat", mo_ta: "Ổ bánh mì nướng bơ nhồi đầy thịt tôm hùm trộn mayonnaise hoặc bơ nóng, đắt mà đáng."},
{ten: "Philly cheesesteak", goc: "", am_thuc: "my", vung: "Philadelphia", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bò thái mỏng xào trên chảo phẳng với hành, phủ phô mai chảy, nhồi trong ổ bánh mì dài."},
{ten: "Pizza New York", goc: "New York-style pizza", am_thuc: "my", vung: "New York", bua: ["trua", "toi", "khuya"], loai: "kho", mo_ta: "Lát pizza to đế mỏng mềm, gập đôi dọc mà ăn trên đường đi, sốt cà chua và mozzarella đơn giản."},
{ten: "Pizza đế dày Chicago", goc: "Chicago deep-dish pizza", am_thuc: "my", vung: "Chicago", bua: ["toi"], loai: "kho", mo_ta: "Pizza nướng trong khuôn sâu như chiếc bánh pie, nhân phô mai dày cộp, sốt cà chua phủ lên trên cùng."},
{ten: "Gà rán miền Nam", goc: "Southern fried chicken", am_thuc: "my", vung: "Miền Nam nước Mỹ", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà ngâm sữa bơ tẩm bột gia vị chiên giòn rụm, vỏ sần vàng nâu, ăn với khoai nghiền và bánh quy."},
{ten: "Bánh pancake siro phong", goc: "Pancakes with maple syrup", am_thuc: "my", vung: "Mỹ", bua: ["sang"], loai: "trangmieng", mo_ta: "Chồng bánh kếp dày xốp đặt miếng bơ trên đỉnh, rưới siro lá phong chảy tràn, bữa sáng cuối tuần."},
{ten: "Bagel cá hồi", goc: "Bagel and lox", am_thuc: "my", vung: "New York", bua: ["sang"], loai: "anvat", mo_ta: "Bánh bagel dai giòn cắt đôi phết phô mai kem, đặt cá hồi hun khói, hành tím và nụ bạch hoa."},
{ten: "Gumbo", goc: "", am_thuc: "my", vung: "Louisiana", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Món hầm sánh từ roux nâu với đậu bắp, xúc xích, tôm và gà, chan lên cơm, hồn của Louisiana."},
{ten: "Jambalaya", goc: "", am_thuc: "my", vung: "New Orleans", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cơm nấu cùng xúc xích hun khói, gà, tôm, ớt chuông và cần tây, cay nồng gia vị Cajun."},
{ten: "Beignet", goc: "", am_thuc: "my", vung: "New Orleans", bua: ["sang", "toi"], loai: "trangmieng", mo_ta: "Bánh rán vuông phồng xốp phủ ngập đường bột trắng, ăn nóng với cà phê sữa bên bờ sông Mississippi."},
{ten: "Bánh táo Mỹ", goc: "Apple pie", am_thuc: "my", vung: "Mỹ", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Vỏ bánh bơ giòn bọc nhân táo quế mềm ngọt, ăn ấm với một muỗng kem vani tan dần."},
{ten: "Cheesecake New York", goc: "New York cheesecake", am_thuc: "my", vung: "New York", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh phô mai kem đặc mịn dày dặn trên đế bánh quy giòn, béo mà thanh, thêm sốt dâu."},
{ten: "Brownie", goc: "", am_thuc: "my", vung: "Chicago", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh sô cô la vuông đặc ẩm như kẹo mềm, mặt nứt giòn, thêm hạt óc chó và kem vani."},
{ten: "Bánh quy sô cô la chip", goc: "Chocolate chip cookie", am_thuc: "my", vung: "Massachusetts", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh quy viền giòn ruột dẻo, những mẩu sô cô la tan chảy, ăn với ly sữa lạnh."},
{ten: "Bánh donut", goc: "Doughnut", am_thuc: "my", vung: "Mỹ", bua: ["sang", "toi"], loai: "anvat", mo_ta: "Vòng bánh rán xốp mềm phủ lớp đường men bóng hoặc sô cô la, rắc cốm màu, đi cùng cà phê."},
{ten: "Bánh mì thịt heo xé", goc: "Pulled pork sandwich", am_thuc: "my", vung: "North Carolina", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Thịt vai heo hun khói xé sợi trộn sốt giấm cay, kẹp bánh mì mềm với salad bắp cải trộn."},
{ten: "Chili con carne", goc: "", am_thuc: "my", vung: "Texas", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Bò băm hầm đậu đỏ, cà chua, ớt và thì là sánh đặc cay ấm, rắc phô mai, ăn với bánh bắp."},
{ten: "Biscuits and gravy", goc: "", am_thuc: "my", vung: "Miền Nam nước Mỹ", bua: ["sang"], loai: "kho", mo_ta: "Bánh quy mặn xốp bơ tách đôi, chan nước sốt sữa với xúc xích và tiêu đen, bữa sáng miền Nam."},
{ten: "Eggs Benedict", goc: "", am_thuc: "my", vung: "New York", bua: ["sang"], loai: "kho", mo_ta: "Bánh muffin nướng, giăm bông, trứng chần lòng đào và sốt hollandaise bơ chanh chảy xuống."},
{ten: "Fajitas", goc: "", am_thuc: "my", vung: "Texas", bua: ["toi"], loai: "nuong", mo_ta: "Thịt bò hoặc gà nướng thái sợi với ớt chuông, hành tây trên chảo gang xèo xèo, cuốn bánh tortilla."},
{ten: "Poke", goc: "", am_thuc: "my", vung: "Hawaii", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cá ngừ sống cắt khối trộn xì dầu, dầu mè, hành, rong biển, đặt trên bát cơm, món tươi mát Hawaii."},
{ten: "Loco moco", goc: "", am_thuc: "my", vung: "Hawaii", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cơm trắng đặt miếng thịt bò băm áp chảo, trứng ốp la và sốt nâu sánh, bữa no nê kiểu Hawaii."},
{ten: "Spam musubi", goc: "", am_thuc: "my", vung: "Hawaii", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Lát thịt hộp áp chảo sốt teriyaki đặt trên khối cơm, quấn rong biển, món ăn vặt mang đi."},
{ten: "Milkshake", goc: "", am_thuc: "my", vung: "Mỹ", bua: ["trua", "toi"], loai: "douong", mo_ta: "Kem vani xay cùng sữa lạnh sánh đặc, phủ kem tươi và quả anh đào, hút bằng ống to."},
{ten: "Key lime pie", goc: "", am_thuc: "my", vung: "Florida", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Nhân sữa đặc chanh ta chua ngọt mát lạnh trên đế bánh quy giòn, phủ kem tươi, món của Florida."},
{ten: "Poutine", goc: "", am_thuc: "my", vung: "Quebec", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Khoai tây chiên phủ phô mai sữa đông kêu ken két và nước sốt gravy nóng, món khuya của Quebec."},
{ten: "Butter tart", goc: "", am_thuc: "my", vung: "Ontario", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Vỏ bánh tart nhỏ giòn với nhân bơ, đường và siro lỏng sánh, có khi thêm nho khô, ngọt đậm."},
{ten: "Thịt bò hun khói Montreal", goc: "Montreal smoked meat", am_thuc: "my", vung: "Montreal", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Ức bò muối gia vị hun khói thái lát dày kẹp bánh mì lúa mạch đen, phết mù tạt vàng."},
{ten: "Bánh Nanaimo", goc: "Nanaimo bar", am_thuc: "my", vung: "British Columbia", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh không nướng ba tầng: đế bánh quy dừa, kem bơ trứng sữa và lớp sô cô la phủ trên cùng."},
{ten: "Tacos al pastor", goc: "", am_thuc: "my", vung: "Thành phố Mexico", bua: ["toi", "khuya"], loai: "anvat", mo_ta: "Thịt heo ướp ớt quay trên trục đứng, lạng mỏng đặt lên bánh tortilla ngô với dứa, hành, rau mùi."},
{ten: "Burrito", goc: "", am_thuc: "my", vung: "Bắc Mexico", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh tortilla bột mì to cuộn chặt thịt, đậu nghiền, cơm, phô mai và sốt, cầm tay ăn no căng."},
{ten: "Quesadilla", goc: "", am_thuc: "my", vung: "Mexico", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh tortilla gập đôi kẹp phô mai Oaxaca kéo sợi, nướng chảo vàng giòn, chấm sốt salsa."},
{ten: "Enchiladas", goc: "", am_thuc: "my", vung: "Mexico", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bánh tortilla cuộn gà, rưới sốt ớt đỏ hoặc xanh, phủ phô mai và kem chua rồi nướng."},
{ten: "Guacamole", goc: "", am_thuc: "my", vung: "Mexico", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bơ chín nghiền thô với hành, cà chua, ớt, rau mùi và chanh, chấm bánh tortilla chiên giòn."},
{ten: "Mole poblano", goc: "", am_thuc: "my", vung: "Puebla", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà phủ sốt mole sẫm màu nấu từ hàng chục loại ớt, gia vị, hạt và sô cô la, sâu lắng khó quên."},
{ten: "Pozole", goc: "", am_thuc: "my", vung: "Jalisco", bua: ["toi"], loai: "nuoc", mo_ta: "Súp hạt ngô to với thịt heo, nước đỏ ớt, rắc bắp cải, củ cải, oregano và vắt chanh."},
{ten: "Tamales", goc: "", am_thuc: "my", vung: "Mexico", bua: ["sang", "trua", "toi"], loai: "kho", mo_ta: "Bột ngô masa nhồi thịt sốt ớt hoặc phô mai, gói vỏ bắp hấp chín, bóc ra mềm thơm."},
{ten: "Chilaquiles", goc: "", am_thuc: "my", vung: "Mexico", bua: ["sang"], loai: "kho", mo_ta: "Bánh tortilla chiên giòn đảo sốt salsa đỏ hay xanh, phủ phô mai, kem chua, trứng ốp la."},
{ten: "Bắp nướng Elote", goc: "Elote", am_thuc: "my", vung: "Mexico", bua: ["toi", "khuya"], loai: "anvat", mo_ta: "Bắp nướng than phết mayonnaise, rắc phô mai cotija, ớt bột và vắt chanh, cầm que mà gặm."},
{ten: "Cochinita pibil", goc: "", am_thuc: "my", vung: "Yucatán", bua: ["sang", "trua"], loai: "kho", mo_ta: "Thịt heo ướp hạt điều màu và cam chua, gói lá chuối nướng chậm, xé sợi ăn với hành ngâm đỏ."},
{ten: "Chiles en nogada", goc: "", am_thuc: "my", vung: "Puebla", bua: ["trua", "toi"], loai: "kho", mo_ta: "Ớt xanh nhồi thịt trái cây, phủ sốt óc chó trắng và hạt lựu đỏ, mang ba màu cờ Mexico."},
{ten: "Huevos rancheros", goc: "", am_thuc: "my", vung: "Mexico", bua: ["sang"], loai: "kho", mo_ta: "Trứng ốp la đặt trên bánh tortilla chiên, rưới sốt cà chua ớt, kèm đậu nghiền và bơ."},
{ten: "Súp tortilla", goc: "Sopa de tortilla", am_thuc: "my", vung: "Thành phố Mexico", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp cà chua ớt khô với sợi tortilla chiên giòn, bơ, phô mai và kem chua, ấm áp mà giòn."},
{ten: "Tlayuda", goc: "", am_thuc: "my", vung: "Oaxaca", bua: ["toi", "khuya"], loai: "anvat", mo_ta: "Bánh tortilla to nướng than phết mỡ, đậu nghiền, phô mai Oaxaca và thịt, được gọi là pizza Mexico."},
{ten: "Carnitas", goc: "", am_thuc: "my", vung: "Michoacán", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt heo om trong mỡ của chính nó đến mềm rồi chiên giòn cạnh, xé nhỏ cuộn tortilla với salsa."},
{ten: "Birria", goc: "", am_thuc: "my", vung: "Jalisco", bua: ["sang", "khuya"], loai: "nuoc", mo_ta: "Thịt dê hoặc bò hầm ớt và gia vị, ăn với bát nước hầm đỏ, nhúng bánh taco vào nước rồi ăn."},
{ten: "Salad Caesar", goc: "Ensalada César", am_thuc: "my", vung: "Tijuana", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Xà lách romaine giòn trộn sốt trứng tỏi cá cơm, phô mai parmesan và bánh mì nướng, ra đời ở Tijuana."},
{ten: "Bánh Tres leches", goc: "Pastel de tres leches", am_thuc: "my", vung: "Mexico", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Bánh bông lan ngâm ba loại sữa ngọt mát mềm ẩm, phủ kem tươi, ăn lạnh bằng thìa."},
{ten: "Horchata", goc: "", am_thuc: "my", vung: "Mexico", bua: ["trua", "toi"], loai: "douong", mo_ta: "Nước gạo xay với quế và đường, trắng đục ngọt mát, uống lạnh cùng tacos cay."},
{ten: "Feijoada", goc: "", am_thuc: "my", vung: "Rio de Janeiro", bua: ["trua"], loai: "nuoc", mo_ta: "Đậu đen hầm với nhiều loại thịt heo và xúc xích, ăn với cơm, cải xào và cam, món trưa thứ Bảy."},
{ten: "Bánh mì phô mai", goc: "Pão de queijo", am_thuc: "my", vung: "Minas Gerais", bua: ["sang", "trua", "toi"], loai: "anvat", mo_ta: "Viên bánh nướng từ bột sắn và phô mai, ngoài giòn nhẹ trong dai dẻo, ăn nóng với cà phê."},
{ten: "Churrasco", goc: "", am_thuc: "my", vung: "Rio Grande do Sul", bua: ["toi"], loai: "nuong", mo_ta: "Thịt bò thăn picanha xiên que nướng than, bồi bàn mang tận bàn cắt từng lát, ăn không giới hạn."},
{ten: "Coxinha", goc: "", am_thuc: "my", vung: "São Paulo", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Vỏ bột khoai nặn hình giọt nước nhân gà xé và phô mai kem, chiên giòn vàng, món ăn vặt quốc dân."},
{ten: "Moqueca", goc: "", am_thuc: "my", vung: "Bahia", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Cá và tôm hầm nồi đất với nước cốt dừa, dầu cọ đỏ, cà chua và ớt chuông, thơm béo rực rỡ."},
{ten: "Bát açaí", goc: "Açaí na tigela", am_thuc: "my", vung: "Pará", bua: ["sang", "trua"], loai: "trangmieng", mo_ta: "Quả açaí tím xay đông như kem trong bát, phủ chuối, granola và mật ong, mát lạnh ngày nóng."},
{ten: "Brigadeiro", goc: "", am_thuc: "my", vung: "Brazil", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Viên kẹo sữa đặc nấu cacao và bơ, lăn cốm sô cô la, có mặt ở mọi bữa tiệc sinh nhật Brazil."},
{ten: "Acarajé", goc: "", am_thuc: "my", vung: "Bahia", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh đậu mắt đen chiên trong dầu cọ đỏ, xẻ đôi nhồi tôm và sốt vatapá, đặc sản Salvador."},
{ten: "Pastel de feira", goc: "", am_thuc: "my", vung: "São Paulo", bua: ["sang", "trua"], loai: "anvat", mo_ta: "Bánh bột mỏng chiên phồng giòn nhân thịt băm hay phô mai, ăn ở chợ phiên kèm nước mía."},
{ten: "Ceviche", goc: "", am_thuc: "my", vung: "Lima", bua: ["trua"], loai: "anvat", mo_ta: "Cá trắng tươi tái trong nước cốt chanh với hành tím, ớt và rau mùi, ăn kèm khoai lang và bắp to."},
{ten: "Lomo saltado", goc: "", am_thuc: "my", vung: "Lima", bua: ["trua", "toi"], loai: "kho", mo_ta: "Bò xào lửa lớn với hành tây, cà chua và xì dầu, trộn khoai tây chiên, ăn với cơm, dấu ấn người Hoa ở Peru."},
{ten: "Ají de gallina", goc: "", am_thuc: "my", vung: "Lima", bua: ["trua", "toi"], loai: "kho", mo_ta: "Gà xé trong sốt kem ớt vàng với bánh mì, óc chó, phô mai, ăn với cơm, khoai và ô liu đen."},
{ten: "Anticuchos", goc: "", am_thuc: "my", vung: "Lima", bua: ["toi", "khuya"], loai: "nuong", mo_ta: "Xiên tim bò ướp ớt panca và giấm nướng than, dai mềm thơm khói, món vỉa hè buổi tối."},
{ten: "Causa limeña", goc: "", am_thuc: "my", vung: "Lima", bua: ["trua"], loai: "anvat", mo_ta: "Khoai tây vàng nghiền vị chanh ớt xếp lớp với gà hoặc cá ngừ trộn sốt, cắt miếng mát lạnh."},
{ten: "Gà nướng Pollo a la brasa", goc: "Pollo a la brasa", am_thuc: "my", vung: "Lima", bua: ["toi"], loai: "nuong", mo_ta: "Gà ướp gia vị quay than củi da giòn sẫm, ăn với khoai tây chiên và sốt ớt xanh."},
{ten: "Papa a la huancaína", goc: "", am_thuc: "my", vung: "Huancayo", bua: ["trua"], loai: "anvat", mo_ta: "Khoai tây luộc phủ sốt kem ớt vàng với phô mai tươi, kèm trứng luộc và ô liu đen."},
{ten: "Arroz chaufa", goc: "", am_thuc: "my", vung: "Lima", bua: ["trua", "toi"], loai: "kho", mo_ta: "Cơm chiên kiểu Hoa của người Peru với trứng, gà, hành lá và xì dầu, món quen trong quán Chifa."},
{ten: "Picarones", goc: "", am_thuc: "my", vung: "Lima", bua: ["toi"], loai: "trangmieng", mo_ta: "Vòng bánh rán làm từ bí đỏ và khoai lang, rưới siro đường mía thơm vỏ cam và quế."},
{ten: "Chicha morada", goc: "", am_thuc: "my", vung: "Peru", bua: ["trua", "toi"], loai: "douong", mo_ta: "Nước nấu từ ngô tím với dứa, quế, đinh hương, màu tím đậm, ngọt chua mát lạnh, không cồn."},
{ten: "Asado", goc: "", am_thuc: "my", vung: "Argentina", bua: ["toi"], loai: "nuong", mo_ta: "Sườn bò, xúc xích, lòng nướng chậm trên than củi, chấm sốt chimichurri, bữa tụ họp cuối tuần."},
{ten: "Empanadas", goc: "", am_thuc: "my", vung: "Salta", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Bánh nướng nhỏ gấp mép xoắn, nhân thịt bò băm, hành, trứng và ô liu, cầm tay ăn nóng."},
{ten: "Choripán", goc: "", am_thuc: "my", vung: "Buenos Aires", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Xúc xích chorizo nướng than xẻ đôi kẹp bánh mì giòn, rưới sốt chimichurri, món sân bóng."},
{ten: "Provoleta", goc: "", am_thuc: "my", vung: "Argentina", bua: ["toi"], loai: "nuong", mo_ta: "Lát phô mai provolone dày nướng trên vỉ đến chảy mềm, rắc oregano và ớt, chấm bánh mì."},
{ten: "Bánh Alfajores", goc: "Alfajores", am_thuc: "my", vung: "Argentina", bua: ["trua", "toi"], loai: "trangmieng", mo_ta: "Hai lớp bánh quy mềm kẹp kem sữa caramel dulce de leche, lăn dừa nạo hoặc nhúng sô cô la."},
{ten: "Trà Mate", goc: "Yerba mate", am_thuc: "my", vung: "Argentina", bua: ["sang", "trua", "toi"], loai: "douong", mo_ta: "Lá yerba mate trong quả bầu khô, châm nước nóng hút qua ống kim loại, chuyền tay nhau uống."},
{ten: "Pastel de choclo", goc: "", am_thuc: "my", vung: "Chile", bua: ["trua", "toi"], loai: "kho", mo_ta: "Nhân thịt bò băm, gà, trứng, ô liu phủ lớp ngô xay ngọt nướng vàng trong bát đất."},
{ten: "Completo", goc: "", am_thuc: "my", vung: "Chile", bua: ["trua", "toi", "khuya"], loai: "anvat", mo_ta: "Xúc xích kẹp bánh mì to phủ bơ nghiền, cà chua thái hạt lựu và mayonnaise, đầy ắp tràn ra."},
{ten: "Salteñas", goc: "", am_thuc: "my", vung: "Bolivia", bua: ["sang"], loai: "anvat", mo_ta: "Bánh nướng vỏ ngọt nhẹ nhân thịt hầm nhiều nước, cắn khéo để nước không chảy, món sáng ở La Paz."},
{ten: "Bandeja paisa", goc: "", am_thuc: "my", vung: "Antioquia", bua: ["trua"], loai: "kho", mo_ta: "Đĩa lớn với cơm, đậu đỏ, thịt băm, bì heo chiên, xúc xích, trứng, chuối chiên và bơ, no tới tối."},
{ten: "Súp Ajiaco", goc: "Ajiaco", am_thuc: "my", vung: "Bogotá", bua: ["trua", "toi"], loai: "nuoc", mo_ta: "Súp gà với ba loại khoai tây, bắp và lá guascas, thêm kem, nụ bạch hoa và bơ, ấm áp xứ núi."},
{ten: "Arepa", goc: "", am_thuc: "my", vung: "Venezuela", bua: ["sang", "trua", "toi"], loai: "anvat", mo_ta: "Bánh bột ngô tròn nướng chảo xẻ đôi, nhồi phô mai, thịt xé, đậu hoặc bơ, ăn mọi bữa trong ngày."},
{ten: "Pabellón criollo", goc: "", am_thuc: "my", vung: "Venezuela", bua: ["trua"], loai: "kho", mo_ta: "Thịt bò xé sợi sốt cà chua, cơm trắng, đậu đen và chuối chín chiên, món quốc hồn Venezuela."},
{ten: "Ropa vieja", goc: "", am_thuc: "my", vung: "Cuba", bua: ["trua", "toi"], loai: "kho", mo_ta: "Thịt bò xé sợi hầm với cà chua, ớt chuông và hành, ăn với cơm và đậu đen, tên món là quần áo cũ."},
{ten: "Bánh mì Cuba", goc: "Cubano", am_thuc: "my", vung: "Miami", bua: ["trua", "toi"], loai: "anvat", mo_ta: "Bánh mì kẹp heo quay, giăm bông, phô mai Thụy Sĩ, dưa chuột muối, mù tạt, ép nóng giòn."},
{ten: "Mofongo", goc: "", am_thuc: "my", vung: "Puerto Rico", bua: ["trua", "toi"], loai: "kho", mo_ta: "Chuối xanh chiên giã với tỏi và tóp mỡ nặn thành chóp, ăn với nước dùng hoặc tôm sốt."},
{ten: "Gà Jerk Jamaica", goc: "Jerk chicken", am_thuc: "my", vung: "Jamaica", bua: ["toi"], loai: "nuong", mo_ta: "Gà ướp ớt scotch bonnet, hạt tiêu Jamaica và cỏ xạ hương, nướng trên gỗ, cay bỏng mà thơm."},
{ten: "Ackee and saltfish", goc: "", am_thuc: "my", vung: "Jamaica", bua: ["sang"], loai: "kho", mo_ta: "Quả ackee mềm vàng như trứng bác xào với cá muối, hành, ớt, món sáng quốc hồn của Jamaica."}
